218:export async function assertPrivateRunDirectory(outputDir: string, runDir: string): Promise<void> {
219:  const contained = (candidate: string, controller: string): boolean => {
220:    const path = relative(candidate, controller);
221:    return path === "" || (!isAbsolute(path) && path !== ".." && !path.startsWith("..\\") && !path.startsWith("../"));
222:  };
223:  if (contained(resolve(outputDir), resolve(runDir))) throw new Error("Run diagnostics directory must be outside the candidate output directory");
224:  await mkdir(runDir, { recursive: true, mode: 0o700 });
225:  if (contained(await realpath(outputDir), await realpath(runDir))) throw new Error("Run diagnostics directory resolves inside the candidate output directory");
226:}
