136:export async function runPipeline(options: PipelineOptions, deps: PipelineDeps): Promise<RunSummary> {
137:  const catalog = await loadRequirementCatalog(options.requirementsFile);
138:  const startedAt = deps.clock.nowMs();
139:  const budget = new RunBudget(options.totalBudgetMs, startedAt, () => deps.clock.nowMs());
140:  const state = new RunStateStore({ statusByRequirementId: catalog.statusById,
141:    acceptedSha: await deps.git.captureAccepted("shallow: initial state"), startedAtMs: startedAt,
142:    totalBudgetMs: options.totalBudgetMs }, options.ledgerFile, deps.logSink ?? null, deps.diagnosticSecrets);
143:  const implemented = new Set<string>();
144:  const packets = auditPackets(catalog);
145:  let featureGrouping = featureGroupPackets(catalog);
146:  const requirementById = new Map(catalog.requirements.map(item => [item.id, item]));
147:  const auditPacketByRequirementId = new Map(packets.flatMap(packet =>
148:    packet.requirementIds.map(id => [id, packet] as const)));
149:  const planCache = new PlanCache(dirname(options.ledgerFile),
150:    options.progressDir ? progressPlansDirectory(options.progressDir) : undefined);
151:  let results = new Map<string, AuditResult>();
152:  let boundaryRepairCount = 0;
153:  let currentBoundaryModule: string | undefined;
154:  let gatewayPhase: PipelinePhase = "implementation";
155:  const preplanAbort = new AbortController();
156:  const pendingPlans = new Map<string, { ready: boolean; failed: boolean; promise: Promise<void> }>();
157:  const noProgressRefinements = new Set<string>();
158:  const recoveryAuditPolicy = { refineLocators: true, noProgressRefinements };
159:  const gateway = deps.gatewayRecovery ?? new GatewayRecovery();
160:  const dependencyClosure = (requirementIds: readonly string[]): Set<string> => {
161:    const closure = new Set<string>();
162:    const pending = requirementIds.flatMap(id => requirementById.get(id)?.dependencyIds ?? []);
163:    while (pending.length > 0) {
164:      const id = pending.pop()!;
165:      if (closure.has(id)) continue;
166:      closure.add(id);
167:      pending.push(...(requirementById.get(id)?.dependencyIds ?? []));
168:    }
169:    return closure;
170:  };
171:  const verificationStatus = (requirementId: string): RequirementStatus => {
172:    const auditPacket = auditPacketByRequirementId.get(requirementId);
173:    return (auditPacket ? results.get(auditPacket.id)?.status : undefined)
174:      ?? state.snapshot.statusByRequirementId[requirementId]
175:      ?? "todo";
176:  };
177:  const dependencyGate = (packet: WorkPacket, moduleId: string): {
178:    unmet: Array<{ id: string; status: RequirementStatus }>;
179:    provisional: string[];
180:  } => {
181:    const packetIds = new Set(packet.requirementIds);
182:    const decided = [...dependencyClosure(packet.requirementIds)]
183:      .filter(id => !packetIds.has(id))
184:      .filter(id => {
185:        const dependency = requirementById.get(id);
186:        const dependencyModuleId = dependency?.folderPath[1] ?? dependency?.id;
187:        const auditPacket = auditPacketByRequirementId.get(id);
188:        // Dependencies in the current, not-yet-audited module remain eligible.
189:        // Other dependencies need a runnable checkpoint before downstream work.
190:        return dependencyModuleId !== moduleId
191:          || (auditPacket !== undefined && results.has(auditPacket.id))
192:          || verificationStatus(id) !== "todo";
193:      })
194:      .map(id => ({ id, status: verificationStatus(id) }))
195:      .sort((left, right) => left.id.localeCompare(right.id));
196:    return { unmet: decided.filter(item => !implemented.has(item.id)),
197:      provisional: decided.filter(item => implemented.has(item.id) && item.status !== "verified").map(item => item.id) };
198:  };
199:  gateway.setRecorder(({ packetId, ...detail }) => state.record({ at: now(), type: "gateway_wait", packetId, detail }));
200:  const planner = deps.planner;
201:  const plannerWindow = (): (() => number) => {
202:    const phase = gatewayPhase;
203:    // GatewayRecovery first reads this after admitting the Planner request.
204:    let deadline: number | undefined;
205:    return () => {
206:      deadline ??= options.totalBudgetMs <= 0 ? deps.clock.nowMs() + PLANNER_RECOVERY_WINDOW_MS : Infinity;
207:      return Math.min(budget.remaining(phase), deadline - deps.clock.nowMs());
208:    };
209:  };
210:  const plannerUsage = (packetId: string, operation: "plan" | "refine" | "review") =>
211:    (usage: ProbePlannerUsage) => state.record({ at: now(), type: "probe_planner_usage", packetId, detail: { operation, ...usage } });
212:  deps = { ...deps, planner: {
213:    plan: (packet, feedback, callOptions) => {
214:      const remaining = plannerWindow();
215:      return gateway.run("planner", packet.id, remaining,
216:        () => planner.plan(packet, feedback, { timeoutMs: Math.max(1, Math.min(callOptions?.timeoutMs ?? Infinity, remaining())),
217:          onUsage: plannerUsage(packet.id, "plan"), onReviewUsage: plannerUsage(packet.id, "review"), signal: callOptions?.signal }), callOptions?.signal);
218:    },
219:    refineLocators: (original, failures, feedback, callOptions) => {
220:      const remaining = plannerWindow();
221:      return gateway.run("planner", original.packetId, remaining,
222:        () => planner.refineLocators(original, failures, feedback, { timeoutMs: Math.max(1, Math.min(callOptions?.timeoutMs ?? Infinity, remaining())),
223:          onUsage: plannerUsage(original.packetId, "refine"), signal: callOptions?.signal }), callOptions?.signal);
224:    },
225:    reviewPlan: (packet, original, failures, feedback, callOptions) => {
226:      const remaining = plannerWindow();
227:      return gateway.run("planner", packet.id, remaining,
228:        () => planner.reviewPlan(packet, original, failures, feedback, { timeoutMs: Math.max(1, Math.min(callOptions?.timeoutMs ?? Infinity, remaining())),
229:          preparationOnlyCaseIds: callOptions?.preparationOnlyCaseIds,
230:          onUsage: plannerUsage(packet.id, "review"), signal: callOptions?.signal }), callOptions?.signal);
231:    },
232:  } };
233:  const backgroundPlanner: Pick<ProbePlanner, "plan"> = {
234:    plan: async (packet, feedback, callOptions) => {
235:      for (;;) {
236:        preplanAbort.signal.throwIfAborted();
237:        try {
238:          return await deps.planner.plan(packet, feedback, {
239:            timeoutMs: callOptions?.timeoutMs ?? Infinity, signal: preplanAbort.signal,
240:          });
241:        } catch (error) {
242:          if (preplanAbort.signal.aborted || !(error instanceof GatewayRequestError) ||
243:            !error.gatewayFailure.retryable || gateway.exhausted || budget.remaining(gatewayPhase) <= 0) throw error;
244:          await state.record({ at: now(), type: "probe_planner_retry", packetId: packet.id,
245:            detail: { source: "planner", message: "鍚庡彴棰勮鍒掓仮澶嶇獥鍙ｈ€楀敖锛岀户缁悗鍙伴噸璇?,
246:              validationError: errorMessage(error) } });
247:        }
248:      }
249:    },
250:  };
251:  deps.candidate?.setRecorder(event => state.record(event));
252:
253:  const phase = async (name: PipelinePhase, round?: number): Promise<void> => {
254:    gatewayPhase = name;
255:    const remaining = budget.remaining(name);
256:    await state.record({ at: now(), type: "phase_started", detail: { phase: name, round,
257:      memory: await memorySnapshot(),
258:      ...(Number.isFinite(remaining) ? { remainingMs: remaining } : {}) } });
259:  };
260:  const build = async (request: BuilderRequest, name: PipelinePhase, runOptions: BuilderRunOptions = {}): Promise<BuilderResult> => {
261:    const packetId = "packet" in request ? request.packet.id : "delivery-repair";
262:    const ceiling = name === "implementation" ? IMPLEMENTATION_CALL_CEILING_MS : name === "repair" ? BOUNDARY_REPAIR_CALL_CEILING_MS : DELIVERY_REPAIR_CALL_CEILING_MS;
263:    const deadline = deps.clock.nowMs() + Math.min(ceiling, runOptions.timeoutMs ?? ceiling);
264:    const remaining = () => Math.min(deadline - deps.clock.nowMs(), budget.remaining(name));
265:    if (remaining() <= 0) return { outcome: "timed_out", sessionId: "unavailable", summary: "phase budget exhausted" };
266:    state.setPacketAttempt(packetId, "packet" in request ? request.packet.attempt : 1);
267:    let lastResult: BuilderResult | undefined;
268:    try {
269:      return await gateway.run("builder", packetId, remaining, async () => {
270:        await state.record({ at: now(), type: "builder_started", packetId, detail: { mode: request.mode } });
271:        const at = deps.clock.nowMs();
272:        let result: BuilderResult;
273:        try { result = await deps.builder.run(request, { ...runOptions, timeoutMs: Math.max(1, Math.floor(remaining())) }); }
274:        catch (error) {
275:          if (error instanceof ExecutionFault) throw error;
276:          result = { outcome: "failed", sessionId: "unavailable", summary: errorMessage(error),
277:            ...(error instanceof GatewayRequestError ? { gatewayFailure: error.gatewayFailure } : {}) };
278:        }
279:        lastResult = result;
280:        await state.record({ at: now(), type: "builder_finished", packetId,
281:          detail: { ...result, durationMs: Math.max(0, deps.clock.nowMs() - at) } });
282:        if (result.referenceImages) await state.record({ at: now(), type: "builder_reference_images", packetId, detail: result.referenceImages });
283:        if (result.outcome !== "completed" && result.gatewayFailure) {
284:          if (request.mode === "implement") await preserveInterruptedWork(request.packet);
285:          throw new GatewayRequestError(result.gatewayFailure);
286:        }
287:        return result;
288:      });
289:    } catch (error) {
290:      if (error instanceof ExecutionFault) throw error;
291:      if (!(error instanceof GatewayRequestError)) throw error;
292:      return { ...lastResult, sessionId: lastResult?.sessionId ?? "unavailable", outcome: "failed",
293:        summary: lastResult?.summary ?? error.message, gatewayFailure: error.gatewayFailure };
294:    }
295:  };
296:  /**
297:   * A gateway outage pauses work instead of ending the run: retry the same
298:   * builder call with a fresh window while the failure is retryable. A
299:   * non-retryable rejection (authentication or a request error) ends the loop
300:   * so the caller can stop dispatching instead of spinning without backoff.
301:   */
302:  const resumeGatewayWork = async (
303:    current: BuilderResult,
304:    emitPause: (failure: NonNullable<BuilderResult["gatewayFailure"]>) => Promise<void>,
305:    retry: () => Promise<BuilderResult>,
306:  ): Promise<BuilderResult> => {
307:    while (current.gatewayFailure?.retryable && current.outcome !== "completed" && !gateway.exhausted) {
308:      await emitPause(current.gatewayFailure);
309:      current = await retry();
310:    }
311:    return current;
312:  };
313:  const stopImplementation = async (packet: WorkPacket,
314:    failure: NonNullable<BuilderResult["gatewayFailure"]>): Promise<void> => {
315:    await state.record({ at: now(), type: "implementation_stopped", packetId: packet.id,
316:      detail: { requirementIds: packet.requirementIds, failure } });
317:  };
318:  const runnable = async (): Promise<CandidateEvidence | undefined> => {
319:    const app = await deps.appLifecycle.start(options.outputDir, options.platformContract);
320:    try { await app.assertUnchanged?.(); }
321:    finally { await app.stop(); }
322:    await app.assertUnchanged?.();
323:    if (app.candidate) await deps.candidate?.assertCurrent(app.candidate);
324:    return app.candidate;
325:  };
326:  const checkpoint = async (ids: string[], reason: string, candidate?: CandidateEvidence): Promise<void> => {
327:    if (candidate) await deps.candidate?.assertCurrent(candidate);
328:    const sha = await deps.git.captureAccepted(`shallow: checkpoint ${reason}`);
329:    if (candidate) await deps.candidate?.assertCurrent(candidate);
330:    state.setAcceptedSha(sha);
331:    if (candidate) deps.candidate?.recordAccepted(candidate);
332:    await state.record({ at: now(), type: "checkpoint_saved", detail: { requirementIds: ids, reason, candidate } });
333:    await emitArc(deps, state, arc => arc.commitHistorySignal("git_commit"));
334:  };
335:  const preserveInterruptedWork = async (packet: WorkPacket): Promise<void> => {
336:    if (!await deps.git.hasApplicationChanges(state.snapshot.acceptedSha)) return;
337:    await deps.git.captureAccepted(`shallow: interrupted attempt ${packet.id}`);
338:    let candidate: CandidateEvidence | undefined;
339:    let preserved = false;
340:    let reason: string | undefined;
341:    const recoveredPlans = new Map<string, ProbePlan>();
342:    try {
343:      candidate = await runnable();
344:      // Interrupted checkpoints must preserve independently established passes.
345:      for (const packetToCheck of packets) {
346:        const previous = results.get(packetToCheck.id);
347:        if (!previous) continue;
348:        const passed = previous.report?.passedCases ?? [];
349:        const plan = previous.plan ?? await planCache.read(packetToCheck);
350:        if (!plan || (previous.status !== "verified" && !passed.length)) continue;
351:        const guard = previous.status === "verified" ? plan : {
352:          ...plan, cases: plan.cases.filter(item => passed.includes(item.id)),
353:        };
354:        const checked = await auditPacket(packetToCheck, guard, options, deps, state,
355:          () => budget.remaining("implementation"), { refineLocators: false, retryPlan: false });
356:        if (checked.status !== "verified") throw new Error(`Interrupted work did not preserve previously passed behavior: ${packetToCheck.requirementIds.join(", ")}`);
357:        if (checked.plan) {
358:          const recovered = mergeCheckedPlan(plan, checked.plan, packetToCheck);
359:          if (probePlanSha256(recovered) !== probePlanSha256(plan)) recoveredPlans.set(packetToCheck.id, recovered);
360:        }
361:      }
362:      preserved = true;
363:    }
364:    catch (error) { reason = errorMessage(error); await deps.git.restoreAccepted(state.snapshot.acceptedSha); }
365:    if (preserved) {
366:      await checkpoint([], `interrupted ${packet.id}`, candidate);
367:      for (const [id, plan] of recoveredPlans) {
368:        results.set(id, { ...results.get(id)!, plan });
369:        await planCache.write(id, plan).catch(() => {});
370:      }
371:    }
372:    await state.record({ at: now(), type: "builder_work_preserved", packetId: packet.id,
373:      detail: { preserved, requirementIds: packet.requirementIds, ...(reason ? { reason } : {}) } });
374:  };
375:  const audit = async (name: PipelinePhase, previous = results): Promise<Map<string, AuditResult>> => {
376:    const audited = new Map<string, AuditResult>();
377:    // Complete missing plans before replaying cached final probes. Runtime edits
378:    // still check previously passed paths first during delivery revalidation.
379:    const ordered = [...packets].sort((a, b) =>
380:      (name === "audit" ? Number(!previous.get(b.id)?.plan) - Number(!previous.get(a.id)?.plan) : 0) ||
381:      Number(previous.get(b.id)?.status === "verified") - Number(previous.get(a.id)?.status === "verified"));
382:    for (const packet of ordered) {
383:      if (!packet.requirementIds.every(id => implemented.has(id))) continue;
384:      const cached = previous.get(packet.id)?.plan ?? await planCache.read(packet);
385:      const result = budget.remaining(name) <= 0
386:        ? { status: "inconclusive" as const, failureKind: "budget" as const, plan: cached, reason: "audit phase budget exhausted" }
387:        : await auditPacket(packet, cached, options, deps, state, () => budget.remaining(name), { refineLocators: false });
388:      // Detection-only audits never refine; persist a freshly planned result so
389:      // future audits skip the LLM call.
390:      if (result.plan && (!cached || probePlanSha256(result.plan) !== probePlanSha256(cached))) {
391:        await planCache.write(packet.id, result.plan).catch(() => {});
392:      }
393:      audited.set(packet.id, result);
394:    }
395:    return audited;
396:  };
397:  const publish = async (): Promise<void> => {
398:    for (const packet of packets) {
399:      const result = results.get(packet.id);
400:      if (!result) continue;
401:      state.markRequirements(packet.requirementIds, result.status);
402:      await state.record({ at: now(), type: "audit_result", packetId: packet.id,
403:        detail: { requirementIds: packet.requirementIds, status: result.status, reason: result.reason,
404:          failureKind: result.failureKind, navigationRecovered: result.navigationRecovered, uncoveredOutcomes: result.coverageGaps?.length } });
405:      // The platform has no inconclusive status: leave implementation completed, never claim passed.
406:      for (const id of packet.requirementIds) {
407:        if (result.status !== "inconclusive") await emitArc(deps, state, arc => arc.requirementState(id, "test", result.status === "verified" ? "passed" : "failed"));
408:        else await emitArc(deps, state, arc => arc.requirementState(id, "implement", "completed"));
409:      }
410:    }
411:  };
412:  const runModuleBoundaryAudit = async (packetIds: string[], moduleId: string, moduleName: string | undefined): Promise<void> => {
413:    gatewayPhase = "audit";
414:    if (budget.remaining("audit") <= 0) return;
415:    // Reset per-module boundary repair quota when switching modules.
416:    if (currentBoundaryModule !== moduleId) {
417:      boundaryRepairCount = 0;
418:      currentBoundaryModule = moduleId;
419:    }
420:    await state.record({ at: now(), type: "phase_started", detail: { phase: "audit" as const,
