429:    // Sample one cached successful path per other module, escalating a miss to
430:    // its full audit and the current boundary's existing repair quota.
431:    const moduleOf = (packet: WorkPacket) => packet.requirements[0].folderPath[1] ?? packet.requirements[0].id;
432:    const coveredModules = new Set(targetPackets.map(moduleOf));
433:    const regressionChecks: Array<{ packet: WorkPacket; plan: ProbePlan }> = [];
434:    for (const packet of packets) {
435:      const previous = results.get(packet.id);
436:      const ownerModule = moduleOf(packet);
437:      if (coveredModules.has(ownerModule) || previous?.status !== "verified" || !previous.plan ||
438:        !packet.requirements.some(item => item.seedDeclarations.length > 0 || item.product.seedData.length > 0)) continue;
439:      const entry = previous.plan.cases.find(item => item.purpose === "happy_path") ??
440:        previous.plan.cases.find(item => item.purpose === "persistence");
441:      if (!entry || budget.remaining("audit") <= 0) continue;
442:      coveredModules.add(ownerModule);
443:      const check = { packet, plan: { ...previous.plan, cases: [entry] } };
444:      regressionChecks.push(check);
445:      const checked = await auditPacket(packet, check.plan, options, deps, state,
446:        () => budget.remaining("audit"), { refineLocators: false, retryPlan: false, checkCoverage: false });
447:      if (checked.status !== "verified") targetPackets.push(packet);
448:      else if (checked.plan) {
449:        check.plan = checked.plan;
450:        const recovered = mergeCheckedPlan(previous.plan, checked.plan, packet);
451:        if (probePlanSha256(recovered) !== probePlanSha256(previous.plan)) {
452:          results.set(packet.id, { ...previous, plan: recovered });
453:          await planCache.write(packet.id, recovered).catch(() => {});
454:        }
455:      }
456:    }
457:    const ordered = [...targetPackets]
458:      .filter(packet => packet.requirementIds.every(id => implemented.has(id)))
459:      .sort((a, b) => Number(results.get(b.id)?.status === "verified") - Number(results.get(a.id)?.status === "verified"));
460:    const boundaryResults = new Map<string, AuditResult>();
461:    while (ordered.length > 0) {
462:      let nextIndex = ordered.findIndex(packet => {
