465:      });
466:      if (nextIndex < 0) nextIndex = ordered.findIndex(packet => pendingPlans.get(packet.id)?.ready);
467:      if (nextIndex < 0) {
468:        await Promise.race(ordered.map(packet => pendingPlans.get(packet.id)!.promise));
