1025:function buildBuilderProjectContext(
1026:  packet: WorkPacket,
1027:  catalog: RequirementCatalog,
1028:  implemented: ReadonlySet<string>,
1029:  startingPoint: PipelineOptions["stageStartingPoint"] = "unknown",
1030:): BuilderProjectContext {
1031:  const first = packet.requirements[0];
1032:  if (!first) throw new Error(`Packet ${packet.id} has no requirements`);
1033:  const dependencyIds = new Set(
1034:    packet.requirements.flatMap((item) => item.dependencyIds),
1035:  );
1036:  const stage = first.product.stage;
1037:  return {
1038:    product: first.product,
1039:    ancestors: dedupeAncestors(
1040:      packet.requirements.flatMap((item) => item.ancestors),
1041:    ),
1042:    satisfiedDependencies: catalog.requirements
1043:      .filter((item) => dependencyIds.has(item.id) && implemented.has(item.id))
1044:      .map((item) => ({ id: item.id, name: item.name, contract: item.text })),
1045:    ...(stage ? { progressiveStage: {
1046:      ...stage,
1047:      startingPoint: startingPoint ?? "unknown",
1048:      externalPrerequisiteIds: [...new Set(packet.requirements.flatMap(item => item.externalDependencyIds ?? []))],
1049:    } } : {}),
1050:  };
1051:}
