1053:function dedupeAncestors(
1054:  ancestors: WorkPacket["requirements"][number]["ancestors"],
1055:): WorkPacket["requirements"][number]["ancestors"] {
1056:  const seen = new Set<string>();
1057:  const unique: WorkPacket["requirements"][number]["ancestors"] = [];
1058:  for (const ancestor of ancestors) {
1059:    if (seen.has(ancestor.id)) continue;
1060:    seen.add(ancestor.id);
1061:    unique.push(ancestor);
1062:  }
1063:  return unique;
1064:}
