1:import { CommandAppLifecycle } from "../final-verifier.js";
2:import type { AppLifecycle } from "../pipeline.js";
3:import type { PlatformContract } from "../types.js";
4:
5:export type AppAction = "start" | "status" | "stop";
6:export interface AppStatus { running: boolean; baseUrl: string }
7:
8:/** Parent-owned: survives Worker termination long enough to finish cleanup. */
9:export class BuilderApp {
10:  private application?: Awaited<ReturnType<AppLifecycle["start"]>>;
11:  private queue: Promise<unknown> = Promise.resolve();
12:  private closed = false;
13:  constructor(private outputDir: string, private contract: PlatformContract,
14:    private lifecycle: AppLifecycle = new CommandAppLifecycle()) {}
15:
16:  run(action: AppAction): Promise<AppStatus> {
17:    if (this.closed) return Promise.reject(new Error("Builder application manager is closed"));
18:    return this.serial(async () => {
19:      if (action === "stop") await this.stop();
20:      if (this.application) {
21:        try { await this.application.assertUnchanged?.(); }
22:        catch { await this.stop(); }
23:      }
24:      if (action === "start" && !this.application) {
25:        this.application = await this.lifecycle.start(this.outputDir, this.contract);
26:      }
27:      return { running: Boolean(this.application), baseUrl: this.contract.baseUrl };
28:    });
29:  }
30:
31:  async close(): Promise<void> {
32:    this.closed = true;
33:    await this.serial(() => this.stop());
34:  }
35:  private async stop(): Promise<void> {
36:    if (this.application) { await this.application.stop(); this.application = undefined; }
37:  }
38:  private serial<T>(operation: () => Promise<T>): Promise<T> {
39:    const result = this.queue.then(operation);
40:    this.queue = result.catch(() => {});
41:    return result;
42:  }
43:}
