169:export function extractJsonPayload(content: string): string {
170:  const trimmed = content.trim();
171:  const fenced = trimmed.match(/^```(?:json)?\s*[\r\n]+([\s\S]*?)[\r\n]*```$/);
172:  const candidate = fenced ? fenced[1] : trimmed;
173:  const blocks = balancedBlocks(candidate);
174:  const parsed = blocks.filter((block) => {
175:    try {
176:      JSON.parse(block);
177:      return true;
178:    } catch {
179:      return false;
180:    }
181:  });
182:  if (parsed.length === 0) return candidate;
183:  return parsed.reduce((best, block) => (block.length > best.length ? block : best));
184:}
