186:function balancedBlocks(content: string): string[] {
187:  const blocks: string[] = [];
188:  let searchFrom = 0;
189:  while (searchFrom < content.length) {
190:    const start = content.indexOf("{", searchFrom);
191:    if (start < 0) break;
192:    let depth = 0;
193:    let inString = false;
194:    let escaped = false;
195:    let end = -1;
196:    for (let index = start; index < content.length; index += 1) {
197:      const char = content[index];
198:      if (inString) {
199:        if (escaped) {
200:          escaped = false;
201:        } else if (char === "\\") {
202:          escaped = true;
203:        } else if (char === '"') {
204:          inString = false;
205:        }
206:        continue;
207:      }
208:      if (char === '"') {
209:        inString = true;
210:      } else if (char === "{") {
211:        depth += 1;
212:      } else if (char === "}") {
213:        depth -= 1;
214:        if (depth === 0) {
215:          end = index;
216:          break;
217:        }
218:      }
219:    }
220:    if (end < 0) {
221:      searchFrom = start + 1;
222:      continue;
223:    }
224:    blocks.push(content.slice(start, end + 1));
225:    searchFrom = end + 1;
226:  }
227:  return blocks;
228:}
