266:function extractContent(value: unknown): { content?: string; usage?: PlannerUsage; cutOff?: boolean } {
267:  if (typeof value !== "object" || value === null) return {};
268:  const record = value as { choices?: unknown; usage?: unknown };
269:  const result: { content?: string; usage?: PlannerUsage; cutOff?: boolean } = {};
270:  const usage = parseUsage(record.usage);
271:  if (usage) result.usage = usage;
272:  const choices = record.choices;
273:  if (!Array.isArray(choices) || choices.length === 0) return result;
274:  const first = choices[0];
275:  if (typeof first !== "object" || first === null) return result;
276:  if ((first as { finish_reason?: string }).finish_reason === "length") result.cutOff = true;
277:  const message = (first as { message?: unknown }).message;
278:  if (typeof message !== "object" || message === null) return result;
279:  const content = (message as { content?: unknown }).content;
280:  if (typeof content === "string") result.content = content;
281:  return result;
282:}
