284:/** Mirrors the Pi provider's normalization: input excludes cached tokens; total is the sum. */
285:function parseUsage(raw: unknown): PlannerUsage | undefined {
286:  if (typeof raw !== "object" || raw === null) return undefined;
287:  const usage = raw as Record<string, unknown>;
288:  const details = typeof usage.prompt_tokens_details === "object" && usage.prompt_tokens_details !== null
289:    ? usage.prompt_tokens_details as Record<string, unknown> : undefined;
290:  const reported = [usage.prompt_tokens, usage.completion_tokens, details?.cached_tokens,
291:    usage.prompt_cache_hit_tokens, details?.cache_write_tokens];
292:  if (!reported.some(value => typeof value === "number" && Number.isFinite(value))) return undefined;
293:  const promptTokens = finiteNumber(usage.prompt_tokens) ?? 0;
294:  const reportedCached = finiteNumber(details?.cached_tokens) ?? finiteNumber(usage.prompt_cache_hit_tokens) ?? 0;
295:  const cacheWrite = finiteNumber(details?.cache_write_tokens) ?? 0;
296:  // Some OpenAI-compatible providers report cached_tokens as (previous hits + current writes).
297:  const cacheRead = cacheWrite > 0 ? Math.max(0, reportedCached - cacheWrite) : Math.max(0, reportedCached);
298:  const output = Math.max(0, finiteNumber(usage.completion_tokens) ?? 0);
299:  const input = Math.max(0, promptTokens - cacheRead - cacheWrite);
300:  return { input, output, cacheRead, cacheWrite, total: input + output + cacheRead + cacheWrite };
301:}
302:
303:function finiteNumber(value: unknown): number | undefined {
304:  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
305:}
