4:export interface CgroupMemoryMount {
5:  version: 1 | 2;
6:  directory: string;
7:}
8:
9:/** Resolve the process's actual cgroup mount, including container mount namespaces. */
10:export async function resolveCgroupMemoryMount(): Promise<CgroupMemoryMount | undefined> {
11:  if (process.platform !== "linux") return undefined;
12:  try {
13:    const groups = (await readFile("/proc/self/cgroup", "utf8")).trim().split("\n");
14:    const mounts = (await readFile("/proc/self/mountinfo", "utf8")).trim().split("\n");
15:    for (const line of mounts) {
16:      const [fields, filesystem] = line.split(" - ");
17:      const version = filesystem.startsWith("cgroup2 ") ? 2 : filesystem.startsWith("cgroup ") && filesystem.split(" ")[2]?.split(",").includes("memory") ? 1 : 0;
18:      if (!version) continue;
19:      const group = groups.find(value => version === 2 ? value.startsWith("0::") : value.split(":")[1].split(",").includes("memory"));
20:      if (!group) continue;
21:      const parts = fields.split(" ").map(value => value.replace(/\\040/g, " "));
22:      const subpath = posix.relative(parts[3], group.split(":").slice(2).join(":"));
23:      const directory = posix.join(parts[4], subpath.startsWith("..") ? "" : subpath);
24:      return { version: version as 1 | 2, directory };
25:    }
26:  } catch { /* Resource counters are diagnostic, never a reason to skip behavior. */ }
27:  return undefined;
28:}
29:
30:export async function memorySnapshot(): Promise<Record<string, unknown>> {
31:  if (process.platform !== "linux") return { status: "unavailable", platform: process.platform };
32:  const mount = await resolveCgroupMemoryMount();
33:  if (!mount) return { status: "unavailable", platform: "linux" };
34:  try {
35:    const names = mount.version === 2 ? ["memory.current", "memory.peak", "memory.max", "memory.events", "memory.swap.max"]
36:      : ["memory.usage_in_bytes", "memory.max_usage_in_bytes", "memory.limit_in_bytes", "memory.failcnt"];
37:    const values: Record<string, string> = {};
38:    for (const name of names) {
39:      const value = await readFile(posix.join(mount.directory, name), "utf8").catch(() => undefined);
40:      if (value !== undefined) values[name] = value.trim();
41:    }
42:    if (Object.keys(values).length) return { status: "available", version: mount.version, directory: mount.directory, ...values };
43:  } catch { /* Resource counters are diagnostic, never a reason to skip behavior. */ }
44:  return { status: "unavailable", platform: "linux" };
45:}
