30:  thresholdRatio?: number;
31:  /** Poll interval while waiting. Default 1s. */
32:  pollMs?: number;
33:  /** Give up waiting and proceed after this long. Default 60s or SHALLOW_MEMORY_GATE_MAX_WAIT_MS. */
34:  maxWaitMs?: number;
