57:  const readUsage = options.readUsage ?? defaultReadUsage();
58:  const onWait = options.onWait ?? defaultOnWait;
59:  return {
60:    async waitForHeadroom(expectedBytes: number, signal?: AbortSignal): Promise<void> {
61:      const started = now();
62:      let polled = false;
63:      let timedOut = false;
64:      let aborted = false;
65:      try {
66:        while (true) {
67:          if (signal?.aborted) { aborted = true; break; }
68:          const usage = await readUsage().catch(() => undefined);
69:          if (!usage || usage.max === undefined || !Number.isFinite(usage.max) || usage.max <= 0) return;
70:          if (usage.current + expectedBytes <= threshold * usage.max) break;
71:          if (maxWaitMs <= 0) break;
72:          if (now() - started >= maxWaitMs) { timedOut = true; break; }
73:          polled = true;
74:          await sleep(pollMs);
75:        }
76:      } finally {
