94:    const mount = await mountPromise;
95:    if (!mount) return undefined;
96:    const [currentName, maxName] = mount.version === 2
97:      ? ["memory.current", "memory.max"]
98:      : ["memory.usage_in_bytes", "memory.limit_in_bytes"];
99:    const [currentRaw, maxRaw] = await Promise.all([
100:      readFile(posix.join(mount.directory, currentName), "utf8"),
101:      readFile(posix.join(mount.directory, maxName), "utf8"),
102:    ]);
103:    const current = Number.parseInt(currentRaw.trim(), 10);
104:    if (!Number.isFinite(current)) return undefined;
105:    const maxText = maxRaw.trim();
106:    const max = maxText === "max" ? undefined : Number.parseInt(maxText, 10);
107:    // cgroup v1 reports ~2^63-page sentinels when no limit is set.
108:    if (max === undefined || !Number.isFinite(max) || max > 2 ** 60) return { current, max: undefined };
109:    return { current, max };
110:  };
111:}
