132:export function selectPromptFragments(
133:  request: BuilderPromptInput,
134:): PromptFragmentId[] {
135:  if (request.mode === "delivery_repair") {
136:    return ["delivery_contract"];
137:  }
138:
139:  const selected = new Set<PromptFragmentId>(
140:    PRODUCT_BASE_FRAGMENTS[request.projectContext.product.kind],
141:  );
142:
143:  if (request.projectContext.product.kind === "generic_web") {
144:    for (const fragment of selectGenericFallbackFragments(request.packet, request.projectContext)) {
145:      selected.add(fragment);
146:    }
147:  }
148:
149:  const observation: BuilderShadowObservation | undefined =
150:    request.mode === "implement" ? undefined : request.shadowObservation;
151:  if (observation) {
152:    if (observation.failures.some((failure) => failure.category === "locator")) {
153:      selected.add("accessible_web_controls");
154:    }
155:    if (observation.applicationStartupFailed) {
156:      selected.add("delivery_contract");
157:    }
158:  }
159:
160:  return FRAGMENT_ORDER.filter((fragment) => selected.has(fragment));
161:}
162:
163:function selectGenericFallbackFragments(
164:  packet: WorkPacket,
165:  context: BuilderProjectContext,
166:): PromptFragmentId[] {
167:  const haystack = [
168:    context.product.rootName,
169:    context.product.description,
170:    ...context.ancestors.flatMap((ancestor) => [ancestor.name, ancestor.description]),
171:    ...packet.requirements.flatMap((requirement) => [
172:      requirement.name,
173:      requirement.text,
174:      ...requirement.scenarios,
175:    ]),
176:  ]
177:    .join("\n")
178:    .toLowerCase();
179:
180:  const selected = new Set<PromptFragmentId>();
181:  for (const entry of GENERIC_FALLBACK_LEXICON) {
182:    if (entry.keywords.some((keyword) => haystack.includes(keyword))) {
183:      selected.add(entry.fragment);
184:    }
185:  }
186:  return [...selected];
187:}
