1:import type { RequirementCatalog } from "./types.js";
2:import { DEFAULT_FEATURE_GROUP_THRESHOLDS, featureGroupingFromIds,
3:  type FeatureGrouping, type FeatureGroupThresholds } from "./scheduler.js";
4:import type { PlannerUsageListener } from "./planner-json-client.js";
5:
6:export interface FeatureGroupingOptions {
7:  timeoutMs: number;
8:  onUsage?: PlannerUsageListener;
9:  signal?: AbortSignal;
10:  feedback?: { validationError: string; cutOffByModel: boolean };
11:}
12:
13:export interface FeatureGrouper {
14:  /** Returns an untrusted proposal; the controller validates it against Catalog. */
15:  group(catalog: RequirementCatalog, options: FeatureGroupingOptions): Promise<unknown>;
16:}
17:
18:export const FEATURE_GROUPING_SCHEMA = {
19:  type: "object", additionalProperties: false, required: ["groups"], properties: {
20:    groups: { type: "array", items: { type: "object", additionalProperties: false,
21:      required: ["requirementIds", "purpose"], properties: {
22:        requirementIds: { type: "array", minItems: 1, maxItems: DEFAULT_FEATURE_GROUP_THRESHOLDS.maxRequirements,
23:          items: { type: "string" } },
24:        purpose: { type: "string", minLength: 1, maxLength: 80 },
25:      } } },
26:  },
27:} as const;
28:
29:export function parseFeatureGrouping(
30:  value: unknown,
31:  catalog: RequirementCatalog,
32:  thresholds: FeatureGroupThresholds = DEFAULT_FEATURE_GROUP_THRESHOLDS,
33:): FeatureGrouping {
34:  const root = record(value, ["groups"], "Feature grouping");
35:  if (!Array.isArray(root.groups)) throw new Error("Feature grouping requires a groups array");
36:  const purposes: string[] = [];
37:  const ids = root.groups.map((value, index) => {
38:    const group = record(value, ["requirementIds", "purpose"], `Feature group ${index + 1}`);
39:    if (!Array.isArray(group.requirementIds) || !group.requirementIds.every(id => typeof id === "string")) {
40:      throw new Error(`Feature group ${index + 1} requires a string requirementIds array`);
41:    }
42:    if (typeof group.purpose !== "string" || !group.purpose.trim() || group.purpose.length > 80) {
43:      throw new Error(`Feature group ${index + 1} requires a purpose of 1..80 characters`);
44:    }
45:    purposes.push(group.purpose);
46:    return group.requirementIds as string[];
47:  });
48:  return { ...featureGroupingFromIds(catalog, ids, thresholds), purposes };
49:}
50:
51:function record(value: unknown, keys: string[], label: string): Record<string, unknown> {
52:  if (typeof value !== "object" || value === null || Array.isArray(value)) throw new Error(`${label} must be an object`);
53:  const result = value as Record<string, unknown>;
54:  for (const key of Object.keys(result)) if (!keys.includes(key)) throw new Error(`${label} has unsupported field: ${key}`);
55:  return result;
56:}
