### agent/agent/src/requirement-text.ts
1:/** Mask data/UI literals without changing offsets, so their punctuation is not prose. */
2:export function maskRequirementLiterals(text: string): string {
3:  return text.replace(/`[^`]*`|"[^"\n]*"|鈥淸^鈥漖*鈥潀鈥榌^鈥橾*鈥?g, literal => "#".repeat(literal.length));
4:}
5:
6:/** Return source sentences without splitting punctuation inside literals. */
7:export function requirementSentences(text: string): string[] {
8:  const prose = maskRequirementLiterals(text);
9:  const sentences: string[] = [];
10:  let start = 0;
11:  for (const separator of prose.matchAll(/[.!?](?=\s|$)|[\r\n]+/g)) {
12:    const end = separator.index! + separator[0].length;
13:    const sentence = text.slice(start, end).trim();
14:    if (sentence) sentences.push(sentence);
15:    start = end;
16:  }
17:  const tail = text.slice(start).trim();
18:  if (tail) sentences.push(tail);
19:  return sentences;
20:}
