11:  category: "system" | "fragments" | "judge" | "planning",
12:  name: string,
13:): string {
14:  const key = `${category}/${name}`;
15:  const cached = cache.get(key);
16:  if (cached !== undefined) return cached;
17:  const assetPath = fileURLToPath(
18:    new URL(`../prompts/${category}/${name}.md`, import.meta.url),
19:  );
20:  let raw: string;
21:  try {
22:    raw = readFileSync(assetPath, "utf8");
23:  } catch (error) {
24:    throw new PromptAssetError(
25:      `Unable to read prompt asset ${key} (looked for ${assetPath}): ${String(error)}`,
26:    );
27:  }
28:  const text = raw.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trimEnd();
29:  cache.set(key, text);
30:  return text;
31:}
32:
33:export function fillTemplate(
34:  template: string,
35:  values: Record<string, string>,
36:): string {
37:  let filled = template;
38:  for (const [key, value] of Object.entries(values)) {
39:    if (value.includes("{{")) {
40:      throw new Error(`Value for placeholder ${key} contains literal "{{"; fillTemplate refuses ambiguous substitution`);
41:    }
42:    filled = filled.split(`{{${key}}}`).join(value);
43:  }
44:  const residual = [...filled.matchAll(TEMPLATE_PLACEHOLDER)].map(
45:    (match) => match[1].trim(),
46:  );
47:  if (residual.length > 0) {
48:    throw new Error(
49:      `Template still has unfilled placeholders after substitution: ${[...new Set(residual)].join(", ")}`,
50:    );
51:  }
52:  return filled;
53:}

