34:export class RunStateStore {
35:  private readonly state: RunStateSnapshot;
36:  private readonly runId = randomUUID();
37:  private firstEventAtMs?: number;
38:  private evidenceCount = 0;
39:  private readonly semanticCorrections = new Map<string, number>();
40:
41:  constructor(
42:    initial: InitialRunState,
43:    private readonly ledgerFile?: string,
44:    private readonly logSink?: LogSink | null,
45:    private readonly secrets: readonly string[] = [],
46:  ) {
47:    this.state = {
48:      ...initial,
49:      statusByRequirementId: { ...initial.statusByRequirementId },
50:      attemptsByPacketId: {},
51:      ledger: [],
52:    };
53:  }
54:
55:  get snapshot(): RunStateSnapshot {
56:    return {
57:      ...this.state,
58:      statusByRequirementId: { ...this.state.statusByRequirementId },
59:      attemptsByPacketId: { ...this.state.attemptsByPacketId },
60:      ledger: [...this.state.ledger],
61:    };
62:  }
63:
64:  markRequirements(ids: string[], status: RequirementStatus): void {
65:    for (const id of ids) {
66:      if (!(id in this.state.statusByRequirementId)) {
67:        throw new Error(`Unknown requirement status key: ${id}`);
68:      }
69:      this.state.statusByRequirementId[id] = status;
70:    }
71:  }
72:
73:  setAcceptedSha(sha: string): void {
74:    this.state.acceptedSha = sha;
75:  }
76:
77:  setPacketAttempt(packetId: string, attempt: number): void {
78:    this.state.attemptsByPacketId[packetId] = attempt;
79:  }
80:
81:  /** Per-run quota fence: each case may receive at most one semantic correction. */
82:  semanticCorrectionCount(packetId: string, caseId: string): number {
83:    return this.semanticCorrections.get(`${packetId}\u0000${caseId}`) ?? 0;
84:  }
85:
86:  noteSemanticCorrection(packetId: string, caseId: string): void {
87:    const key = `${packetId}\u0000${caseId}`;
88:    this.semanticCorrections.set(key, (this.semanticCorrections.get(key) ?? 0) + 1);
89:  }
90:
91:  /** Bounded, source-free failure evidence; neither full plans nor raw browser traces. */
92:  async saveEvidence(report: ShadowReport, plan?: ProbePlan): Promise<string | undefined> {
93:    if (!this.ledgerFile || report.failures.length === 0 || this.evidenceCount >= 128) return undefined;
94:    const id = `${this.runId}-${++this.evidenceCount}`;
95:    const evidence = {
96:      id, packetId: sanitizeDiagnosticText(report.packetId, this.secrets), verdict: report.verdict,
97:      acceptedSha: this.state.acceptedSha, attempt: this.state.attemptsByPacketId[report.packetId],
98:      ...(report.candidate ? { candidate: report.candidate } : {}),
99:      ...(plan ? { planSha256: probePlanSha256(plan) } : {}),
100:      failureCount: report.failures.length,
101:      failures: report.failures.slice(0, 8).map((failure) => {
102:        const step = plan?.cases.find((item) => item.id === failure.caseId)?.steps[failure.stepIndex];
103:        return {
104:          caseId: sanitizeDiagnosticText(failure.caseId, this.secrets), stepIndex: failure.stepIndex,
105:          category: failure.category, message: sanitizeDiagnosticText(failure.message, this.secrets),
106:          ...(failure.pageUrl ? { pageUrl: sanitizeDiagnosticText(failure.pageUrl, this.secrets, 1_000) } : {}),
107:          ...(failure.inputSummary ? { inputSummary: sanitizeDiagnosticText(failure.inputSummary, this.secrets) } : {}),
108:          ...(failure.locatorSnapshot ? { accessibilityExcerpt: sanitizeDiagnosticText(failure.locatorSnapshot, this.secrets) } : {}),
109:          ...(step && "locator" in step ? {
110:            locators: locatorCandidates(step.locator).map((locator) => sanitizeEvidenceLocator(locator, this.secrets)),
111:          } : {}),
112:          ...(failure.locatorAttempts ? {
113:            locatorAttempts: failure.locatorAttempts.slice(0, 4).map((attempt) => ({
114:              locator: sanitizeEvidenceLocator(attempt.locator, this.secrets),
115:              message: sanitizeDiagnosticText(attempt.message, this.secrets),
116:              ...(attempt.matchCount === undefined ? {} : { matchCount: attempt.matchCount }),
117:            })),
118:          } : {}),
119:        };
120:      }),
121:    };
122:    try {
123:      const payload = `${JSON.stringify(evidence)}\n`;
124:      if (Buffer.byteLength(payload) > 128 * 1024) return undefined;
125:      const directory = join(dirname(this.ledgerFile), "evidence");
126:      await mkdir(directory, { recursive: true, mode: 0o700 });
127:      await writeFile(join(directory, `${id}.json`), payload, { encoding: "utf8", mode: 0o600, flag: "wx" });
128:      return id;
129:    } catch {
130:      await this.record({ at: new Date().toISOString(), type: "evidence_write_failed", packetId: report.packetId });
131:      return undefined;
132:    }
133:  }
134:
135:  async record(event: RunEvent): Promise<void> {
136:    const sequence = this.state.ledger.length + 1;
137:    const atMs = Date.parse(event.at);
138:    this.firstEventAtMs ??= atMs;
139:    const safeEvent = redactEvent({ ...event, runId: this.runId,
140:      eventId: `${this.runId}:${sequence}`, sequence, phase: eventPhase(event),
141:      elapsedMs: Math.max(0, atMs - this.firstEventAtMs),
142:      acceptedSha: this.state.acceptedSha,
143:      ...(event.packetId ? { attempt: this.state.attemptsByPacketId[event.packetId] } : {}),
144:    }, this.secrets);
145:    this.state.ledger.push(safeEvent);
146:    try {
147:      // Planner response previews are private controller diagnostics, not public stderr.
148:      this.logSink?.write(`${JSON.stringify(safeEvent, (key, value: unknown) => key === "contentPreview" ? undefined : value)}\n`);
149:    } catch {
150:      // Diagnostic sink failures must never change the decision path.
151:    }
152:    if (!this.ledgerFile) return;
153:    try {
154:      await mkdir(dirname(this.ledgerFile), { recursive: true });
155:      await appendFile(this.ledgerFile, `${JSON.stringify(safeEvent)}\n`, { encoding: "utf8", mode: 0o600 });
156:    } catch {
157:      // Ledger file failures must never change the decision path.
158:    }
159:  }
160:}
161:
162:function redactEvent(event: RunEvent, secrets: readonly string[]): RunEvent {
163:  return JSON.parse(JSON.stringify(event, (key, value: unknown) => {
164:    if (/^(?:api[_-]?key|authorization|password|secret|cookie|token|access[_-]?token|refresh[_-]?token)$/i.test(key)) return "[redacted]";
165:    if (/^(?:plan|probePlan|locatorSnapshot|trace|screenshot)$/i.test(key)) return undefined;
166:    if (typeof value === "string") return sanitizeDiagnosticText(value, secrets);
167:    return value;
168:  })) as RunEvent;
169:}
170:
171:function sanitizeEvidenceLocator(locator: ProbeLocator, secrets: readonly string[]): ProbeLocator {
172:  const exact = locator.exact === undefined ? {} : { exact: locator.exact };
173:  const scope = locator.scope ? { scope: { ...sanitizeEvidenceLocator(locator.scope as ProbeLocator, secrets),
174:    ...(locator.scope.hasText === undefined ? {} : { hasText: sanitizeDiagnosticText(locator.scope.hasText, secrets) }) } } : {};
175:  return locator.by === "role"
176:    ? { by: "role", role: sanitizeDiagnosticText(locator.role, secrets), ...exact, ...scope,
177:      ...(locator.name === undefined ? {} : { name: sanitizeDiagnosticText(locator.name, secrets) }) }
178:    : { by: locator.by, text: sanitizeDiagnosticText(locator.text, secrets), ...exact, ...scope };
179:}
180:
181:function eventPhase(event: RunEvent): RunEvent["phase"] {
182:  if (event.type.startsWith("arc_")) return "projection";
183:  if (event.type.startsWith("evidence_")) return "evidence";
184:  if (event.type.startsWith("builder_")) return "builder";
185:  if (event.type.startsWith("application_")) return "application";
186:  if (event.type.startsWith("candidate_")) return "application";
187:  if (event.type.startsWith("delivery_") || event.type.startsWith("verification_")) return "delivery";
188:  if (event.type.startsWith("probe_plan") || event.type === "probe_preplan_failed" || event.type.startsWith("probe_refin")) return "planner";
189:  if (event.type.startsWith("probe_")) return "probe";
190:  if (event.type.startsWith("packet_")) return "decision";
191:  return "pipeline";
192:}
