3:
4:/**
5: * Directory the controller mirrors run progress (human log lines and probe
6: * plans) into so the platform's product view exposes it. It is intentionally
7: * NOT ignored: the platform filters gitignored paths out of the delivered
8: * template, so ignoring it would hide it. Instead it is kept untracked
9: * (excluded from `git add`), excluded from acceptance digests and preserved by
10: * rollbacks, exactly like `.arc` 鈥?but unlike `.arc` the platform does not hide
11: * it. Builder tools are blocked from reading it because it carries hidden Judge
12: * plans.
13: */
14:export const PROGRESS_DIR_NAME = "shallow-progress";
15:
16:/** True when a repository-relative path is the progress directory or below it. */
17:export function isProgressPath(relativePath: string): boolean {
18:  const normalised = relativePath.replaceAll("\\", "/");
19:  return normalised === PROGRESS_DIR_NAME || normalised.startsWith(`${PROGRESS_DIR_NAME}/`);
20:}
21:
22:export function progressPlansDirectory(progressDir: string): string {
23:  return join(progressDir, "plans");
24:}
25:
26:/** Append-only, best-effort journal inside the packaged product directory. */
27:export class ProgressJournal {
28:  readonly directory: string;
29:  readonly logFile: string;
30:
31:  constructor(outputDir: string) {
32:    this.directory = join(outputDir, PROGRESS_DIR_NAME);
33:    this.logFile = join(this.directory, "progress.log");
34:  }
35:
36:  appendLine(line: string): void {
37:    try {
38:      mkdirSync(this.directory, { recursive: true });
39:      appendFileSync(this.logFile, `${line}\n`, "utf8");
40:    } catch {
41:      // Diagnostics must never change the decision path.
42:    }
43:  }
44:}
