1:import { cp, readdir, stat, writeFile } from "node:fs/promises";
2:import { fileURLToPath } from "node:url";
3:import { basename, join, resolve } from "node:path";
4:
5:import type { PlatformContract } from "./types.js";
6:
7:export type StarterScaffoldStatus =
8:  | "installed"
9:  | "skipped_existing_application"
10:  | "skipped_nonempty_output";
11:
12:export interface StarterScaffoldResult {
13:  status: StarterScaffoldStatus;
14:  reason: string;
15:  files: string[];
16:}
17:
18:const EMPTY_OUTPUT_METADATA = new Set([
19:  ".arc",
20:  ".git",
21:  ".gitignore",
22:  "requirements",
23:  "shallow-progress",
24:]);
25:const SCAFFOLD_RUNTIME_ARTIFACTS = new Set(["node_modules", "dist", "build"]);
26:
27:/**
28: * Installs only the task-neutral platform shell, accessible UI primitives and
29: * unconnected infrastructure helpers. Business navigation, API routes, domain
30: * data, composed product views and requirement behavior remain Builder-owned.
31: */
32:export async function installStarterScaffold(
33:  outputDir: string,
34:  contract: PlatformContract,
35:  assetRoot = fileURLToPath(new URL("../scaffold/minimal-web/", import.meta.url)),
36:): Promise<StarterScaffoldResult> {
37:  const root = resolve(outputDir);
38:  const entries = await readdir(root);
39:  const [frontendExists, backendExists] = await Promise.all([
40:    isDirectory(join(root, "frontend")),
41:    isDirectory(join(root, "backend")),
42:  ]);
43:  if (frontendExists && backendExists) {
44:    return {
45:      status: "skipped_existing_application",
46:      reason: "frontend and backend already exist",
47:      files: [],
48:    };
49:  }
50:
51:  const applicationEntries = entries.filter(name => !EMPTY_OUTPUT_METADATA.has(name));
52:  if (frontendExists || backendExists || applicationEntries.length > 0) {
53:    return {
54:      status: "skipped_nonempty_output",
55:      reason: frontendExists || backendExists
56:        ? "partial frontend/backend layout already exists"
57:        : `output contains existing project files: ${applicationEntries.slice(0, 5).join(", ")}`,
58:      files: [],
59:    };
60:  }
61:
62:  await cp(join(assetRoot, "frontend"), join(root, "frontend"), {
63:    recursive: true,
64:    errorOnExist: true,
65:    force: false,
66:    filter: source => !SCAFFOLD_RUNTIME_ARTIFACTS.has(basename(source)),
67:  });
68:  await cp(join(assetRoot, "backend"), join(root, "backend"), {
69:    recursive: true,
70:    errorOnExist: true,
71:    force: false,
72:    filter: source => !SCAFFOLD_RUNTIME_ARTIFACTS.has(basename(source)),
73:  });
74:  await writeFile(
75:    join(root, "backend", "src", "platform-ports.json"),
76:    `${JSON.stringify(contract.extraPorts ?? [], null, 2)}\n`,
77:    "utf8",
78:  );
79:  const files = await listFiles(root, ["frontend", "backend"]);
80:  return {
81:    status: "installed",
82:    reason: "installed task-neutral web capability and platform shell",
83:    files,
84:  };
85:}
86:
87:async function isDirectory(path: string): Promise<boolean> {
88:  try {
89:    return (await stat(path)).isDirectory();
90:  } catch (error) {
91:    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
92:    throw error;
93:  }
94:}
95:
96:async function listFiles(root: string, directories: string[]): Promise<string[]> {
97:  const files: string[] = [];
98:  const visit = async (relative: string): Promise<void> => {
99:    for (const entry of await readdir(join(root, relative), { withFileTypes: true })) {
100:      const child = `${relative}/${entry.name}`;
101:      if (entry.isDirectory()) await visit(child);
102:      else if (entry.isFile()) files.push(child);
103:    }
104:  };
105:  for (const directory of directories) await visit(directory);
106:  return files.sort();
107:}
