296:    messages: Array<{ role: "system" | "user"; content: string }>,
297:    timeoutMs = this.config.timeoutMs,
298:    schema: unknown = PROBE_PLAN_JSON_SCHEMA,
299:    onUsage?: ProbePlannerUsageListener,
