305:  private parse(
306:    content: string,
307:    packet: Pick<WorkPacket, "id" | "requirementIds"> & Partial<Pick<WorkPacket, "requirements">>,
308:  ): ProbePlan {
309:    let value: unknown;
310:    try {
311:      value = JSON.parse(extractJsonPayload(content));
312:    } catch (error) {
313:      throw new ProbePlannerError("json", "Probe planner content is not JSON", {
314:        cause: error,
315:        content,
316:        apiKey: this.config.apiKey,
317:      });
318:    }
319:    try {
320:      if (value && typeof value === "object" && Object.hasOwn(value, "navigationRecovered")) {
321:        throw new Error("Planner cannot supply controller navigation recovery evidence");
322:      }
323:      const plan = parseProbePlan(value, packet);
324:      if (packet.requirements) assertCoverageAccountedFor(plan, packet.requirements);
325:      return plan;
326:    } catch (error) {
327:      throw new ProbePlannerError("schema", "Probe planner content violates ProbePlan", {
328:        cause: error,
329:        content,
330:        apiKey: this.config.apiKey,
331:      });
332:    }
333:  }
