43:/** Only reproducible business failures are eligible for application repair. */
44:export async function auditPacket(packet: WorkPacket, cached: ProbePlan | undefined,
45:  options: PipelineOptions, deps: PipelineDeps, state: RunStateStore, remaining: () => number,
46:  policy: AuditPolicy = DEFAULT_AUDIT_POLICY,
47:): Promise<AuditResult> {
48:  const result = await performAudit(packet, cached, options, deps, state, remaining, policy);
49:  if (result.plan?.navigationRecovered) result.navigationRecovered = true;
50:  if (result.status === "verified" && result.plan && policy.checkCoverage !== false) {
51:    const gaps = probeCoverageGaps(result.plan, packet.requirements);
52:    if (gaps.length) return { ...result, status: "inconclusive", failureKind: "coverage", coverageGaps: gaps,
53:      reason: `${gaps.length} scenario outcomes lack verified assertion coverage` };
54:  }
55:  if (result.status === "inconclusive" && !result.failureKind) {
56:    result.failureKind = result.report?.failures.some(item => item.category === "precondition") ? "preparation"
57:      : result.report?.failures.some(item => item.category === "locator") ? "locator"
58:      : result.report?.failures.some(item => item.category === "runner") ? "execution" : "unreproduced";
59:  }
60:  return result;
61:}
