63:async function performAudit(packet: WorkPacket, cached: ProbePlan | undefined,
64:  options: PipelineOptions, deps: PipelineDeps, state: RunStateStore, remaining: () => number,
65:  policy: AuditPolicy,
66:): Promise<AuditResult> {
67:  let plan = cached;
68:  try {
69:    if (remaining() <= 0) return { status: "inconclusive", failureKind: "budget", plan, reason: "audit budget exhausted" };
70:    plan ??= await planProbe(packet, options, deps, state, remaining, policy.retryPlan !== false);
71:    if (!plan) return { status: "inconclusive", failureKind: "planning", reason: "probe planner failed" };
72:    await state.record({ at: now(), type: "probe_planned", packetId: packet.id, detail: { cases: plan.cases.length } });
73:    const recovery = { browserRetries: 0, locatorRefinements: 0 };
74:    let first = await runShadowProbes(packet, plan, options, deps, state, recovery, remaining, policy);
75:    plan = first.plan;
76:    const reviewKey = createHash("sha256").update(JSON.stringify([probePlanSha256(plan), first.report.failures])).digest("hex");
77:    let reviewed = policy.refineLocators && policy.noProgressRefinements?.has(`review:sound:${reviewKey}`) === true;
78:    const probeGap = first.report.failures.some(item => item.category === "locator" || item.category === "precondition");
79:    // Business review keeps its own quota even when another case cannot be
80:    // prepared. Pure preparation/control gaps share the locator-recovery quota.
81:    const reviewUsesRecoveryQuota = probeGap && !first.report.failures.some(isBehaviorFailure);
82:    const reviewAttempts = reviewUsesRecoveryQuota
83:      ? MAX_LOCATOR_REFINEMENTS - recovery.locatorRefinements : DEFAULT_SEMANTIC_REVIEW_ATTEMPTS;
84:    if (policy.refineLocators && first.report.verdict !== "pass" && first.source === "probe" &&
85:      first.report.failures.some(item => item.category !== "runner") && !reviewed && reviewAttempts > 0 && remaining() > 0) {
86:      if (policy.noProgressRefinements?.has(`review:unavailable:${reviewKey}`)) {
87:        return { status: "inconclusive", failureKind: "review", plan, report: first.report, reason: "Identical plan review previously could not establish valid evidence" };
88:      }
89:      const review = await reviewBehaviorFailures(packet, plan, first.report, deps, state, remaining, reviewAttempts,
90:        reviewUsesRecoveryQuota ? recovery : undefined);
91:      if (review.status === "unavailable") {
92:        if (review.failureKind !== "gateway") policy.noProgressRefinements?.add(`review:unavailable:${reviewKey}`);
93:        return { status: "inconclusive", failureKind: review.failureKind ?? "review", plan, report: first.report, reason: review.reason };
94:      }
95:      reviewed = true;
96:      if (review.status === "sound") policy.noProgressRefinements?.add(`review:sound:${reviewKey}`);
97:      if (review.status === "corrected") {
98:        plan = review.plan;
99:        first = await runShadowProbes(packet, plan, options, deps, state, recovery, remaining, policy);
100:        plan = first.plan;
101:      }
102:    }
103:    if (first.report.verdict === "pass") {
104:      if (!first.navigationRecovered) return { status: "verified", plan, report: first.report };
105:      if (remaining() <= 0) return { status: "inconclusive", failureKind: "budget", plan, report: first.report, reason: "navigation recovery confirmation budget exhausted" };
106:      const confirmed = await runShadowProbes(packet, plan, options, deps, state, recovery, remaining, { refineLocators: false });
107:      return confirmed.report.verdict === "pass"
108:        ? { status: "verified", plan, report: confirmed.report }
109:        : { status: "inconclusive", plan, report: confirmed.report, reason: "navigation recovery did not pass on a fresh application" };
110:    }
111:    const businessFailures = first.report.failures.filter(isBehaviorFailure);
112:    const diagnosis = reviewed ? diagnosticFailures(packet, plan, first.report) : [];
113:    if (first.source !== "probe" || (!businessFailures.length && !diagnosis.length) ||
114:      (policy.refineLocators && businessFailures.length > 0 && !reviewed)) {
115:      return { status: "inconclusive", plan, report: first.report, reason: "Judge could not establish valid behavior evidence" };
116:    }
117:    if (remaining() <= 0) return { status: "inconclusive", failureKind: "budget", plan, reason: "failure confirmation budget exhausted" };
118:    // Fresh application state: failed actions may have changed server-side data.
119:    const confirmed = await runShadowProbes(packet, plan, options, deps, state, recovery, remaining, { refineLocators: false });
120:    plan = confirmed.plan;
121:    if (diagnosis.length > 0 && businessFailures.length === 0 && confirmed.source === "probe" && confirmed.report.verdict === "pass") {
122:      return { status: "verified", plan, report: confirmed.report };
123:    }
124:    const repeated = confirmed.source === "probe" ? confirmed.report.failures.filter(item =>
125:      [...businessFailures, ...diagnosis].some(previous => failureKey(previous) === failureKey(item))) : [];
126:    const reproducedBusiness = repeated.filter(isBehaviorFailure);
127:    if (reproducedBusiness.length > 0) {
128:      return { status: "failed", plan, report: { ...confirmed.report, verdict: "fail", failures: reproducedBusiness } };
129:    }
130:    const reproducedDiagnosis = repeated.filter(item => diagnosis.some(previous => failureKey(previous) === failureKey(item)));
131:    return { status: "inconclusive", plan,
132:      report: reproducedDiagnosis.length ? { ...confirmed.report, verdict: "inconclusive", failures: reproducedDiagnosis } : confirmed.report,
133:      ...(reproducedDiagnosis.length ? { repairableProbeFailure: true,
