174:  const beforePlanSha256 = probePlanSha256(plan);
175:  const preparationOnlyCaseIds = report.failures.filter(failure => failure.category === "precondition" &&
176:    (plan.cases.find(item => item.id === failure.caseId)?.setupStepCount ?? 0) > 0).map(item => item.caseId);
177:  let feedback: ProbePlannerFeedback | undefined;
178:  for (let attempt = 0; attempt < attempts; attempt += 1) {
179:    if (remaining() <= 0) break;
180:    try {
181:      if (recovery) recovery.locatorRefinements++;
182:      const review = await deps.planner.reviewPlan(packet, plan, report.failures, feedback, {
183:        timeoutMs: Math.max(1, remaining()),
184:        preparationOnlyCaseIds,
185:      });
186:      if (review.status === "sound") {
187:        const unprepared = report.failures.filter(failure => {
188:          const probeCase = plan.cases.find(item => item.id === failure.caseId);
189:          const seeded = packet.requirements.some(item => probeCase?.requirementIds.includes(item.id) && item.seedDeclarations.length > 0);
190:          if (!seeded) return false;
191:          if (failure.category === "precondition") {
192:            const step = probeCase?.steps[failure.stepIndex];
193:            return (step?.op === "expectValue" || step?.op === "expectText") &&
194:              !probeCase?.steps.slice(0, failure.stepIndex).some(step =>
195:              ["fill", "select", "setChecked", "drag", "uploadFile"].includes(step.op) ||
196:              (step.op === "press" && step.key === "ControlOrMeta+V"));
197:          }
198:          if (!isBehaviorFailure(failure)) return false;
199:          const count = probeCase?.setupStepCount ?? 0;
200:          const stateAssertion = probeCase?.steps.slice(0, count).some(step => step.op.startsWith("expect") &&
201:            !(step.op === "expectVisible" && step.locator.by === "role" &&
202:              ["main", "grid", "region", "group", "list", "dialog", "article"].includes(step.locator.role)));
203:          return count === 0 || failure.stepIndex < count || !stateAssertion;
204:        });
205:        if (unprepared.length) {
206:          throw new Error(`Sound review requires an executed initial-state checkpoint for seeded cases: ${unprepared.map(item => item.caseId).join(", ")}. ` +
207:            "Seed declarations and a visible page/grid do not prove the required values, identity or permissions. Reconstruct preparation with grounded state assertions and setupStepCount.");
208:        }
209:        if (report.failures.length && report.failures.every(failure => failure.category === "precondition" &&
210:          !isLocatorAmbiguity(failure) && !groundedPreparationTarget(packet, plan, failure))) {
211:          throw new Error("Sound preparation review requires requirement-grounded targets. " +
212:            "The missing preparation controls or containers are planner assumptions; correct the prefix using the visible page and requirement evidence.");
213:        }
214:        await state.record({ at: now(), type: "probe_reviewed", packetId: packet.id,
215:          detail: { verdict: "sound", rationale: review.rationale, beforePlanSha256 } });
216:        return { status: "sound" };
217:      }
218:      const preparationCorrections = new Set(review.corrections.filter(correction => {
219:        const before = plan.cases.find(item => item.id === correction.caseId)!;
220:        const after = review.plan.cases.find(item => item.id === correction.caseId)!;
221:        const preparationOnly = isPreparationOnlyCorrection(before, after);
222:        if (preparationOnlyCaseIds.includes(correction.caseId) && !preparationOnly) {
223:          throw new Error(`Preparation recovery must preserve the tested steps, inputs and assertions for ${correction.caseId}`);
224:        }
225:        return preparationOnly;
226:      }).map(item => item.caseId));
227:      const exhausted = review.corrections.filter(correction => !preparationCorrections.has(correction.caseId) &&
228:        state.semanticCorrectionCount(packet.id, correction.caseId) >= 1);
229:      if (exhausted.length > 0) {
230:        const reason = `semantic correction quota exhausted for: ${exhausted.map(item => item.caseId).join(", ")}`;
231:        await state.record({ at: now(), type: "probe_review_failed", packetId: packet.id,
232:          detail: { message: reason, planSha256: beforePlanSha256 } });
233:        return { status: "unavailable", reason };
234:      }
235:      for (const correction of review.corrections) {
236:        if (!preparationCorrections.has(correction.caseId)) state.noteSemanticCorrection(packet.id, correction.caseId);
237:      }
238:      await state.record({ at: now(), type: "probe_reviewed", packetId: packet.id,
239:        detail: { verdict: "corrected", rationale: review.rationale, beforePlanSha256,
240:          planSha256: probePlanSha256(review.plan), corrections: review.corrections } });
241:      return { status: "corrected", plan: review.plan };
242:    } catch (error) {
243:      if (error instanceof ExecutionFault || (error instanceof ProbePlannerError && error.fatal)) throw error;
244:      const detail = plannerFailureDetail(error);
245:      await state.record({ at: now(), type: "probe_review_failed", packetId: packet.id,
246:        detail: { ...detail, planSha256: beforePlanSha256 } });
247:      if (error instanceof GatewayRequestError) return { status: "unavailable", failureKind: "gateway", reason: "gateway recovery window exhausted" };
248:      feedback = error instanceof ProbePlannerError
249:        ? { validationError: String(detail.validationError ?? detail.message),
250:            ...(typeof detail.contentPreview === "string" ? { contentPreview: detail.contentPreview } : {}) }
251:        : { validationError: errorMessage(error) };
252:    }
253:  }
254:  return { status: "unavailable", reason: "semantic review could not establish valid probe evidence" };
255:}
