257:/** Candidate misses with no equivalent visible control require path/setup review. */
258:function locatorPatchMayHelp(failure: ShadowReport["failures"][number], step: ProbeStep): boolean {
259:  if (!failure.locatorAttempts || !failure.locatorSnapshot || isLocatorAmbiguity(failure) ||
260:    step.op.startsWith("expect") || !("locator" in step)) return true;
261:  return equivalentSnapshotControls(failure, step.locator).length > 0;
262:}
263:
264:function equivalentSnapshotControls(failure: ShadowReport["failures"][number], locator: ProbeLocator): string[] {
265:  if (!failure.locatorSnapshot) return [];
266:  const roles = /^(button|link|menuitem|menuitemcheckbox|menuitemradio|checkbox|radio|switch|tab|treeitem|option|textbox|searchbox|combobox|spinbutton|gridcell|rowheader|columnheader)$/;
267:  const controls = [...failure.locatorSnapshot.matchAll(/^\s*- ([a-z]+) ("(?:\\.|[^"\\])*")/gm)];
268:  return controls.flatMap(([, role, encoded]) => {
269:    if (!roles.test(role)) return [];
270:    let name: string;
271:    try { name = JSON.parse(encoded); } catch { return []; }
272:    return locatorCandidates(locator).some(candidate => {
273:      const target = candidate.by === "role" ? candidate.name : candidate.text;
274:      return target === undefined ? candidate.by === "role" && role === candidate.role
275:        : candidate.exact === false ? name.includes(target) : name === target;
276:    }) ? [role] : [];
277:  });
278:}
279:
280:function isLocatorAmbiguity(failure: ShadowReport["failures"][number]): boolean {
281:  return failure.message.includes("strict mode violation") ||
282:    failure.locatorAttempts?.some(attempt => attempt.message.includes("strict mode violation") ||
283:      (attempt.matchCount ?? 0) > 1) === true;
284:}
285:
286:function groundedPreparationTarget(packet: WorkPacket, plan: ProbePlan, failure: ShadowReport["failures"][number]): boolean {
287:  const step = plan.cases.find(item => item.id === failure.caseId)?.steps[failure.stepIndex];
288:  if (!step) return false;
289:  const locators = "locator" in step ? [step.locator] : step.op === "drag" ? [step.from, step.to] : [];
290:  return locators.length > 0 && locators.every(locator => groundedLocatorNames(locator, packet).length > 0 &&
291:    (!locator.scope || (locator.scope.by === "role" && !locator.scope.name) ||
292:      groundedLocatorNames(locator.scope, packet).length > 0) && groundedControlRole(locator, packet, failure, step.op));
293:}
294:
295:function groundedControlRole(locator: ProbeLocator, packet: WorkPacket, failure: ShadowReport["failures"][number], operation: ProbeStep["op"]): boolean {
296:  const declared = declaredLocatorRoles(locator, packet, operation);
297:  if (declared.length) return locatorCandidates(locator).every(candidate => matchesDeclaredLocatorRole(candidate, declared));
298:  const observed = equivalentSnapshotControls(failure, locator);
299:  // An existing same-named control does not justify changing its role to a
300:  // planner assumption. Recover the locator/prefix before diagnosing the app.
301:  return !observed.length || locatorCandidates(locator).some(candidate =>
302:    (candidate.by === "role" && observed.includes(candidate.role)) || candidate.by === "label");
303:}
304:
305:function diagnosticFailures(packet: WorkPacket, plan: ProbePlan, report: ShadowReport): ShadowReport["failures"] {
306:  return report.failures.filter(failure => {
307:    if (isLocatorAmbiguity(failure)) return false;
308:    if (failure.category === "precondition") return groundedPreparationTarget(packet, plan, failure);
309:    if (failure.category !== "locator" || !failure.locatorSnapshot) return false;
310:    const steps = plan.cases.find(item => item.id === failure.caseId)?.steps;
311:    const step = steps?.[failure.stepIndex];
312:    // A prior successful interaction establishes that we reached the flow;
313:    // an absent initial page locator alone is not evidence against the app.
314:    return step && ["click", "fill", "select", "doubleClick"].includes(step.op) && "locator" in step &&
315:      groundedLocatorNames(step.locator, packet).length > 0 &&
316:      groundedControlRole(step.locator, packet, failure, step.op) &&
317:      steps!.slice(0, failure.stepIndex).some(item => ["click", "fill", "select"].includes(item.op));
318:  });
319:}
