321:async function runShadowProbes(
322:  packet: WorkPacket,
323:  plan: ProbePlan,
324:  options: PipelineOptions,
325:  deps: PipelineDeps,
326:  state: RunStateStore,
327:  recovery: { browserRetries: number; locatorRefinements: number },
328:  remaining: () => number,
329:  policy: AuditPolicy,
330:): Promise<ProbeOutcome> {
331:  await state.record({ at: now(), type: "application_starting", packetId: packet.id });
332:  let application: Awaited<ReturnType<AppLifecycle["start"]>>;
333:  try {
334:    application = await deps.appLifecycle.start(
335:      options.outputDir,
336:      options.platformContract,
337:    );
338:  } catch (error) {
339:    await state.record({
340:      at: now(),
341:      type: "application_start_failed",
342:      packetId: packet.id,
343:      detail: { message: errorMessage(error) },
344:    });
345:    return { source: "application", report: applicationFailureReport(packet.id, error), plan };
346:  }
347:
348:  let applicationRunning = true;
349:  const stopApplication = async (): Promise<void> => {
350:    if (!applicationRunning) return;
351:    try {
352:      await application.stop();
353:      await application.assertUnchanged?.();
354:      if (application.candidate) await deps.candidate?.assertCurrent(application.candidate);
355:    } finally {
356:      applicationRunning = false;
357:      await state.record({ at: now(), type: "application_stopped", packetId: packet.id });
358:    }
359:  };
360:  try {
361:    await state.record({ at: now(), type: "application_ready", packetId: packet.id,
362:      detail: { baseUrl: application.baseUrl, ...(application.candidate ? { candidate: application.candidate } : {}) } });
363:    let currentPlan = plan;
364:    const runOptions = { stepTimeoutMs: 2_000, caseTimeoutMs: 15_000 };
365:    let applicationUsed = false;
366:    const prepareCase = async (): Promise<string> => {
367:      if (remaining() <= 0) throw new Error("Audit phase budget exhausted");
368:      if (applicationUsed) {
369:        await application.assertUnchanged?.();
370:        await stopApplication();
371:        await state.record({ at: now(), type: "application_starting", packetId: packet.id });
372:        try {
373:          application = await deps.appLifecycle.start(options.outputDir, options.platformContract);
374:          applicationRunning = true;
375:        } catch (error) {
376:          await state.record({ at: now(), type: "application_start_failed", packetId: packet.id,
377:            detail: { message: errorMessage(error) } });
378:          throw error;
379:        }
380:        await state.record({ at: now(), type: "application_ready", packetId: packet.id,
381:          detail: { baseUrl: application.baseUrl, ...(application.candidate ? { candidate: application.candidate } : {}) } });
382:      }
383:      applicationUsed = true;
384:      return application.baseUrl;
385:    };
386:    const run = async (): Promise<ShadowReport> => {
387:      while (true) {
388:        if (remaining() <= 0) throw new Error("Audit phase budget exhausted");
389:        const startedAt = deps.clock.nowMs();
390:        await state.record({ at: now(), type: "probe_started", packetId: packet.id,
391:          detail: { cases: currentPlan.cases.length, retryCount: recovery.browserRetries,
392:            planSha256: probePlanSha256(currentPlan) } });
393:        try {
394:          const report = await deps.runner.run(currentPlan, { baseUrl: application.baseUrl, ...runOptions, prepareCase,
395:            caseTimeoutMs: Math.max(1, Math.min(runOptions.caseTimeoutMs, remaining())) });
396:          await application.assertUnchanged?.();
397:          if (application.candidate) report.candidate = application.candidate;
398:          const evidenceId = await state.saveEvidence(report, currentPlan);
399:          await state.record({ at: now(), type: "probe_finished", packetId: packet.id,
400:            detail: { verdict: report.verdict, refined: recovery.locatorRefinements > 0, passed: report.passedCases.length,
401:              failed: report.failures.length, durationMs: Math.max(0, deps.clock.nowMs() - startedAt),
402:              categories: report.failures.map((failure) => failure.category), evidenceId,
403:              ...(report.candidate ? { candidate: report.candidate } : {}) } });
404:          return report;
405:        } catch (error) {
406:          if (!(error instanceof ExecutionFault)) throw error;
407:          const retry = error.retryable && recovery.browserRetries < 1 &&
408:            remaining() > 0;
409:          await state.record({ at: now(), type: "execution_fault", packetId: packet.id,
410:            detail: { source: error.source, code: error.code, retryable: error.retryable,
411:              retry, attempt: packet.attempt, retryCount: recovery.browserRetries } });
412:          if (!retry) throw error;
413:          recovery.browserRetries += 1;
414:        }
415:      }
416:    };
417:    let report = await run();
418:    let navigationRecovered = false;
419:    const beforeNavigationPlan = currentPlan;
420:    const beforeNavigationReport = report;
421:    for (let attempt = 0; attempt < 2 && remaining() > 0; attempt++) {
422:      let searchPlan: ProbePlan | undefined;
423:      try { searchPlan = rootSearchNavigationPlan(packet, currentPlan, report); }
424:      catch (error) {
425:        await state.record({ at: now(), type: "execution_fault", packetId: packet.id,
426:          detail: { source: "judge", message: `Navigation recovery plan rejected: ${errorMessage(error)}`, retry: false } });
427:        break;
428:      }
429:      if (!searchPlan) break;
430:      const beforePlan = currentPlan;
431:      const previousReport = report;
432:      currentPlan = searchPlan;
433:      const searched = await run();
434:      navigationRecovered ||= searched.passedCases.length > previousReport.passedCases.length ||
435:        searched.failures.some(failure => {
436:          const previous = previousReport.failures.find(item => item.caseId === failure.caseId);
437:          const step = beforePlan.cases.find(item => item.id === failure.caseId)?.steps[previous?.stepIndex ?? -1];
438:          if (!step || (step.op !== "click" && step.op !== "expectVisible") ||
439:            step.locator.by !== "role" || step.locator.role !== "link") return false;
440:          const targetName = step.locator.name;
441:          const targetIndex = currentPlan.cases.find(item => item.id === failure.caseId)?.steps.findIndex(item =>
442:            item.op === step.op && item.locator.by === "role" && item.locator.name === targetName) ?? -1;
443:          return targetIndex >= 0 && failure.stepIndex > targetIndex;
444:        });
445:      await state.record({ at: now(), type: "probe_navigation_attempted", packetId: packet.id,
446:        detail: { recovered: searched.verdict === "pass", improved: navigationRecovered,
447:          beforePlanSha256: probePlanSha256(beforePlan),
448:          planSha256: probePlanSha256(searchPlan) } });
449:      report = searched;
450:    }
451:    if (currentPlan !== beforeNavigationPlan && !navigationRecovered) {
452:      return { source: "probe", report: beforeNavigationReport, plan: beforeNavigationPlan };
453:    }
454:    // Accepted navigation changes establish the baseline for locator-only
455:    // patches. Keep its requirement anchors across successive refinements.
456:    const refinementBaseline = currentPlan;
457:    const anchoredNames = groundedLocatorAnchors(refinementBaseline, packet);
458:
459:    let feedback: ProbePlannerFeedback | undefined;
460:    const refinableFailures = () => report.failures.filter(failure => {
461:      const step = currentPlan.cases.find(item => item.id === failure.caseId)?.steps[failure.stepIndex];
462:      const locatorFailure = failure.category === "locator" ||
463:        (failure.category === "precondition" && (isLocatorAmbiguity(failure) ||
464:          (failure.locatorAttempts?.length && failure.locatorAttempts.every(attempt => attempt.matchCount === 0) &&
465:            step && "locator" in step && equivalentSnapshotControls(failure, step.locator).length > 0)));
466:      return locatorFailure && failure.locatorSnapshot && step && "locator" in step && locatorPatchMayHelp(failure, step);
467:    });
468:    while (policy.refineLocators &&
469:      report.verdict !== "pass" &&
470:      refinableFailures().length > 0 &&
471:      recovery.locatorRefinements < MAX_LOCATOR_REFINEMENTS &&
472:      remaining() > 0) {
473:      const failures = refinableFailures();
474:      const noProgressKey = createHash("sha256").update(JSON.stringify([
475:        probePlanSha256(currentPlan), failures.map(item => [item.caseId, item.stepIndex, item.locatorSnapshot]),
476:      ])).digest("hex");
477:      if (policy.noProgressRefinements?.has(noProgressKey)) break;
478:      const refinementAttempt = ++recovery.locatorRefinements;
479:      const beforePlanSha256 = probePlanSha256(currentPlan);
480:      let refined: ProbePlan;
481:      try {
482:        // Pass a copy so a planner implementation cannot mutate the behavior being checked.
483:        refined = parseProbePlan(await deps.planner.refineLocators(
484:          structuredClone(currentPlan), structuredClone(failures), feedback,
485:          { timeoutMs: Math.max(1, remaining()), anchoredNames },
486:        ));
487:        assertLocatorOnlyRefinement(currentPlan, refined, failures);
488:        // Keep the baseline's requirement anchors across successive refinements.
489:        assertLocatorOnlyRefinement(refinementBaseline, refined, [], packet);
490:      } catch (error) {
491:        if (error instanceof ExecutionFault || (error instanceof ProbePlannerError && error.fatal)) throw error;
492:        const detail = plannerFailureDetail(error);
493:        feedback = {
494:          validationError: String(detail.validationError ?? detail.message),
495:          ...(typeof detail.contentPreview === "string" ? { contentPreview: detail.contentPreview } : {}),
496:        };
497:        await state.record({ at: now(), type: "probe_refinement_failed", packetId: packet.id,
498:          detail: { ...detail, refinementAttempt, planSha256: beforePlanSha256 } });
499:        if (!(error instanceof GatewayRequestError)) {
500:          policy.noProgressRefinements?.add(noProgressKey);
501:        }
502:        // Rejected/unchanged patches cannot repair missing steps. Reserve the
503:        // remaining recovery call for reviewing the navigation and preparation.
504:        break;
505:      }
506:      if (remaining() <= 0) break;
507:      currentPlan = refined;
508:      feedback = undefined;
509:      await state.record({ at: now(), type: "probe_refined", packetId: packet.id,
510:        detail: { refinementAttempt, beforePlanSha256, planSha256: probePlanSha256(currentPlan) } });
511:      // Browser failures use their own shared quota, outside the planner error handler.
512:      report = await run();
513:    }
514:    return { source: "probe", report, plan: currentPlan, navigationRecovered };
515:  } finally {
516:    await stopApplication();
517:  }
518:}
