520:const MAX_LOCATOR_REFINEMENTS = 2;
521:
522:async function planProbe(
523:  packet: WorkPacket,
524:  options: PipelineOptions,
525:  deps: PipelineDeps,
526:  state: RunStateStore,
527:  remaining: () => number,
528:  retry: boolean,
529:): Promise<ProbePlan | undefined> {
530:  await state.record({ at: now(), type: "probe_planning", packetId: packet.id });
531:  let feedback: ProbePlannerFeedback | undefined;
532:  try {
533:    return parseProbePlan(await deps.planner.plan(packet, undefined, { timeoutMs: Math.max(1, remaining()) }), packet);
534:  } catch (error) {
535:    const cutOffByModel = isModelLengthCutoff(error);
536:    feedback = planValidationFeedback(error);
537:    await state.record({
538:      at: now(),
539:      type: !retry || (error instanceof ProbePlannerError && error.fatal && !cutOffByModel)
540:        ? "probe_planner_failed" : "probe_planner_retry",
541:      packetId: packet.id,
542:      detail: { ...plannerFailureDetail(error), attempt: packet.attempt, retryCount: 0 },
543:    });
544:    if (error instanceof ProbePlannerError && error.fatal && !cutOffByModel) throw error;
545:    if (error instanceof GatewayRequestError) throw error;
546:  }
547:  if (!retry) return undefined;
548:  if (remaining() <= 0) return undefined;
549:  const retryDelayMs = options.plannerRetryDelayMs ?? 2_000;
550:  if (retryDelayMs > 0) {
551:    await new Promise((resolvePromise) => setTimeout(resolvePromise, Math.min(retryDelayMs, remaining())));
552:  }
553:  if (remaining() <= 0) return undefined;
554:  try {
555:    return parseProbePlan(await deps.planner.plan(packet, feedback, { timeoutMs: Math.max(1, remaining()) }), packet);
556:  } catch (error) {
557:    await state.record({
558:      at: now(),
559:      type: "probe_planner_failed",
560:      packetId: packet.id,
561:      detail: plannerFailureDetail(error),
562:    });
563:    if (error instanceof ProbePlannerError && error.fatal) throw error;
564:    if (error instanceof GatewayRequestError) throw error;
565:    return undefined;
566:  }
567:}
568:
569:function plannerFailureDetail(error: unknown): Record<string, unknown> {
570:  return error instanceof ProbePlannerError
571:    ? { source: "planner", ...error.diagnostics }
572:    : { message: errorMessage(error) };
573:}
574:
575:function applicationFailureReport(packetId: string, error: unknown): ShadowReport {
576:  return {
577:    packetId,
578:    verdict: "fail",
579:    passedCases: [],
580:    failures: [
581:      {
582:        caseId: "<application>",
583:        stepIndex: -1,
584:        category: "runner",
585:        message: errorMessage(error),
586:      },
587:    ],
588:  };
589:}
590:
591:function errorMessage(error: unknown): string {
592:  return error instanceof Error ? error.message : String(error);
593:}
