10:/** A packet as `parseProbePlan` accepts it: the cache must re-validate on read. */
11:type CachedPacket = Pick<WorkPacket, "id" | "requirementIds"> &
12:  Partial<Pick<WorkPacket, "requirements" | "prerequisites">>;
13:
14:/**
15: * Disk-backed probe plan cache keyed by audit packet ID.
16: *
17: * Plans and one validation-feedback retry run alongside Builder execution.
18: * Module audits consume ready plans while remaining generation continues.
19: * After locator refinement the refined plan overwrites the entry.
20: * A cached plan is only reused when it still validates against its packet, so
21: * coverage and locator-anchoring rules hold for the cache path too.
22: */
23:export class PlanCache {
24:  private readonly directory: string;
25:
26:  constructor(
27:    runDirectory: string,
28:    /** Optional product-visible mirror so a delivered run exposes its plans. */
29:    private readonly mirrorDirectory?: string,
30:  ) {
31:    this.directory = join(runDirectory, "plans");
32:  }
33:
34:  async read(packet: CachedPacket): Promise<ProbePlan | undefined> {
35:    try {
36:      const raw = await readFile(this.pathFor(packet.id), "utf8");
37:      const plan = parseProbePlan(JSON.parse(raw), packet);
38:      if (packet.requirements) assertCoverageAccountedFor(plan, packet.requirements);
39:      return plan;
40:    } catch {
41:      return undefined;
42:    }
43:  }
44:
45:  async write(packetId: string, plan: ProbePlan): Promise<void> {
46:    await mkdir(this.directory, { recursive: true, mode: 0o700 });
47:    const payload = JSON.stringify(plan);
48:    await writeFile(this.pathFor(packetId), payload, { encoding: "utf8", mode: 0o600 });
49:    if (this.mirrorDirectory) {
50:      await mkdir(this.mirrorDirectory, { recursive: true }).catch(() => {});
51:      await writeFile(join(this.mirrorDirectory, this.fileName(packetId)), payload, { encoding: "utf8" }).catch(() => {});
52:    }
53:  }
54:  private pathFor(packetId: string): string {
55:    return join(this.directory, this.fileName(packetId));
56:  }
57:  private fileName(packetId: string): string {
58:    // Slugified ids are lossy (`A.1` and `A_1` collapse), so the digest keeps files distinct.
59:    const digest = createHash("sha256").update(packetId).digest("hex").slice(0, 16);
60:    return `${sanitise(packetId)}-${digest}.json`;
61:  }
62:}
63:
64:function sanitise(value: string): string {
65:  return value.replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 96);
66:}
67:
68:/**
69: * Kick off plan generation alongside Builder execution.
70: * The returned promise resolves independently of the Builder; its result is
71: * written to the cache when ready so the audit can read from disk later.
72: */
73:export function spawnPlanGeneration(
74:  packet: WorkPacket,
75:  auditPacketId: string,
76:  planner: Pick<ProbePlanner, "plan">,
77:  cache: PlanCache,
78:  timeoutMs: number,
79:  onFailure?: (error: unknown) => Promise<void>,
80:): Promise<ProbePlan | undefined> {
81:  const generate = async (): Promise<ProbePlan> => {
82:    try { return parseProbePlan(await planner.plan(packet, undefined, { timeoutMs }), packet); }
83:    catch (error) {
84:      const feedback = planValidationFeedback(error);
85:      if (!feedback) throw error;
86:      return parseProbePlan(await planner.plan(packet, feedback, { timeoutMs }), packet);
87:    }
88:  };
89:  return generate()
90:    .then(async (plan) => {
91:      await cache.write(auditPacketId, plan);
92:      return plan;
93:    })
94:    .catch(async error => {
95:      await onFailure?.(error).catch(() => {});
96:      return undefined;
97:    });
98:}

