228:function createRunLogSink(runLogFile: string, journal?: ProgressJournal): LogSink {
229:  const runLogDir = dirname(runLogFile);
230:  const formatter = new HumanRunFormatter();
231:  return {
232:    write: (chunk) => {
233:      process.stderr.write(chunk);
234:      const line = formatter.format(chunk);
235:      if (line === null) return;
236:      mkdirSync(runLogDir, { recursive: true });
237:      appendFileSync(runLogFile, `${line}\n`, "utf8");
238:      journal?.appendLine(line);
239:    },
240:  };
241:}
