7:export class PromptBuilder implements BuilderPort {
8:  private textOnly = false;
9:  private visionUnsupported = false;
10:  private visionProbed = false;
11:  constructor(private client: CodingAgentPort, private options: { timeoutMs: number; requirementsDir?: string; contextWindow?: number;
12:    /** Reference images are opt-in; without this no image is read or attached. */
13:    referenceImages?: boolean; visionProbe?: VisionCapability }) {}
14:  async run(request: BuilderRequest, options: BuilderRunOptions = {}): Promise<BuilderResult> {
15:    const timeoutMs = Math.min(this.options.timeoutMs, options.timeoutMs ?? this.options.timeoutMs);
16:    const deadline = Date.now() + timeoutMs;
17:    const remainingMs = () => Math.max(0, deadline - Date.now());
18:    const references = "packet" in request ? request.packet.requirements.flatMap(req => req.references) : [];
19:    // An inconclusive probe must leave images enabled for the normal Builder
20:    // gateway recovery and image rejection fallback. Reserve most of the call
21:    // for implementation when its window is short.
22:    if (this.options.referenceImages && !this.textOnly && !this.visionProbed && this.options.visionProbe && references.length > 0) {
23:      this.visionUnsupported = (await this.options.visionProbe.supports(Math.floor(remainingMs() / 10))) === "unsupported";
24:      this.visionProbed = true;
25:    }
26:    const prompt = compileBuilderPrompt(request);
27:    if (remainingMs() <= 0) return { sessionId: "unavailable", outcome: "timed_out",
28:      summary: "Builder call deadline exhausted during reference-image preflight" };
29:    const attachReferences = Boolean(this.options.referenceImages) && !this.textOnly && !this.visionUnsupported;
30:    const input: CodingAgentRequest = { ...prompt, outputDir: request.outputDir,
31:      timeoutMs: remainingMs(), sessionKey: options.sessionKey, platformContract: request.platformContract, requirementsDir: this.options.requirementsDir,
32:      references, textOnly: this.textOnly, attachReferences, visionUnsupported: this.visionUnsupported,
33:      contextWindow: this.options.contextWindow };
34:    if (options.continuationFeedback) input.taskPrompt += "\n\n" + loadPrompt("system", "implementation-continuation")
35:      .replace("{{FAILURE}}", () => options.continuationFeedback!);
36:    if (options.resumeInterrupted) input.taskPrompt += "\n\n" + loadPrompt("system", "implementation-resume");
37:    let result = await this.client.run(input);
38:    if (result.imageUnsupported && !this.textOnly && remainingMs() > 0) {
39:      this.textOnly = true;
40:      result = await this.client.run({ ...input, textOnly: true, timeoutMs: remainingMs() });
41:    }
42:    // Session paths and SDK internals stay private to the execution adapter.
43:    return { sessionId: result.sessionId, outcome: result.outcome, summary: result.summary, referenceImages: result.referenceImages, execution: result.execution,
44:      ...(result.terminationReason ? { terminationReason: result.terminationReason } : {}),
45:      ...(result.gatewayFailure ? { gatewayFailure: result.gatewayFailure } : {}) };
46:  }
47:  close(): Promise<void> { return this.client.close(); }
48:}
