13:export async function assertToolPath(root: string, input: string): Promise<string> {
14:  const canonicalRoot = await realpath(root);
15:  const path = resolve(canonicalRoot, input);
16:  const contained = (value: string) => {
17:    const rel = relative(canonicalRoot, value);
18:    if (isAbsolute(rel) || rel === ".." || rel.startsWith(`..${process.platform === "win32" ? "\\" : "/"}`) || rel.split(/[\\/]/).some(part => part.toLowerCase() === ".arc" || part.toLowerCase() === PROGRESS_DIR_NAME)) {
19:      throw new Error("Tool path is outside the application or accesses private controller evidence");
20:    }
21:  };
22:  contained(path);
23:  let parent = path;
24:  while (true) {
25:    try { contained(await realpath(parent)); break; }
26:    catch (error) {
27:      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
28:      const next = dirname(parent);
29:      if (next === parent) throw error;
30:      parent = next;
31:    }
32:  }
33:  return path;
34:}
