38:  if (/\.arc|run-ledger|run-log|shallow-progress|\/workspace\/tests|\.codex|\.pi[\\/]|(?:^|[\s"'])\.\.[\\/]/i.test(command)) {
39:    throw new Error("Command accesses controller/private or external paths");
40:  }
41:}
