46:/**
47: * Test execution goes through run_tests so suite concurrency stays memory-bounded;
48: * ad-hoc test commands in shell bypass that bound and are rejected deterministically.
49: * Each pipeline segment is tokenized and anchored on the executable/subcommand, so
50: * searches (`grep vitest`) and unrelated scripts (`npm run build -- --mode test`)
51: * still work. This is a guard, not a sandbox.
52: */
53:export function assertNotTestCommand(command: string): void {
54:  if (pipelineSegments(command).some(isTestSegment)) {
55:    throw new Error("Test commands are not allowed in shell; use the run_tests tool instead: run_tests { target: 'frontend' | 'backend' | 'all', filter?: string }");
56:  }
57:}
