59:function pipelineSegments(command: string): string[][] {
60:  return command.split(/\|\||&&|\||;|\r?\n/).map(segment =>
61:    (segment.match(/"[^"]*"|'[^']*'|\S+/g) ?? []).map(token => token.replace(/^(["'])(.*)\1$/, "$2")));
62:}
63:
64:function stripAssignments(tokens: string[]): string[] {
65:  let index = 0;
66:  while (index < tokens.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(tokens[index])) index += 1;
67:  return tokens.slice(index);
68:}
