70:function executableName(token: string): string {
71:  const name = token.replace(/\\/g, "/").split("/").pop() ?? token;
72:  return name.replace(/\.(?:cmd|exe|mjs|cjs|js)$/i, "").replace(/@[^/]*$/, "").toLowerCase();
73:}
