81:function isTestSegment(raw: string[]): boolean {
82:  const tokens = stripAssignments(raw);
83:  if (!tokens.length) return false;
84:  const executable = executableName(tokens[0]);
85:  const args = tokens.slice(1);
86:  if (executable === "vitest") return true;
87:  if (executable === "node") return nodeRunsTests(args);
88:  if (PACKAGE_MANAGERS.has(executable)) return packageManagerRunsTests(args);
89:  if (BINARY_RUNNERS.has(executable)) return binaryRunnerRunsTests(args);
90:  return false;
91:}
92:
93:function nodeRunsTests(args: string[]): boolean {
94:  if (args.some(arg => arg === "--test")) return true;
95:  return args.some(arg => /(?:^|\/)vitest(?:\.mjs|\.cjs|\.js)?$/i.test(arg.replace(/\\/g, "/")));
96:}
97:
98:function packageManagerRunsTests(args: string[]): boolean {
99:  const argumentsBeforeForwarding = leadingArguments(args).filter(token => token.length > 0);
100:  const nonFlags = argumentsBeforeForwarding.filter(token => !token.startsWith("-"));
101:  const execIndex = nonFlags.findIndex(token => ["exec", "dlx", "x"].includes(token.toLowerCase()));
102:  if (execIndex !== -1) return nonFlags.slice(execIndex + 1).some(token => executableName(token) === "vitest");
103:  const runIndex = nonFlags.findIndex(token => ["run", "run-script"].includes(token.toLowerCase()));
104:  if (runIndex !== -1) {
105:    const script = nonFlags[runIndex + 1];
106:    return script !== undefined && scriptNameIsTest(script);
107:  }
108:  const first = nonFlags[0];
109:  if (first !== undefined && (first.toLowerCase() === "t" || first.toLowerCase() === "test")) return true;
110:  if (first !== undefined && executableName(first) === "vitest") return true;
111:  // Flag values can precede the subcommand (e.g. `npm --prefix frontend test`).
112:  const last = nonFlags.at(-1);
113:  return last !== undefined && (last.toLowerCase() === "t" || last.toLowerCase() === "test");
114:}
115:
116:function binaryRunnerRunsTests(args: string[]): boolean {
117:  const tokens = leadingArguments(args);
118:  const first = tokens.find(token => !token.startsWith("-"));
119:  if (first !== undefined && executableName(first) === "vitest") return true;
120:  return tokens.slice(1).includes("--test");
121:}
