123:function scriptNameIsTest(name: string): boolean {
124:  const normalized = name.toLowerCase();
125:  if (normalized === "test" || normalized === "tests") return true;
126:  return normalized.split(/[:.\-]/).some(part => part === "test" || part === "tests");
127:}
