129:export function createPiTools(cwd: string, managedApp = false): ToolDefinition[] {
130:  const read = createReadToolDefinition(cwd) as unknown as ToolDefinition;
131:  const guardedRead = { ...read, execute: async (...args: Parameters<typeof read.execute>) => {
132:    const params = args[1] as { path: string };
133:    await assertToolPath(cwd, params.path);
134:    return (read.execute as ToolDefinition["execute"])(args[0], args[1], args[2], args[3], args[4]);
135:  } } as ToolDefinition;
136:  const writable = [createEditToolDefinition(cwd), createWriteToolDefinition(cwd)] as unknown as ToolDefinition[];
137:  const guardedWritable = writable.map(tool => ({ ...tool, execute: async (...args: Parameters<typeof tool.execute>) => {
138:    const params = args[1] as { path: string };
139:    await assertToolPath(cwd, params.path);
140:    return (tool.execute as ToolDefinition["execute"])(args[0], args[1], args[2], args[3], args[4]);
141:  } })) as ToolDefinition[];
142:  const shell = createBashToolDefinition(cwd, { operations: {
143:    exec: async (command, directory, { onData, signal, timeout }) => {
144:      assertToolCommand(command);
145:      assertNotTestCommand(command);
146:      await assertToolPath(cwd, directory);
147:      signal?.throwIfAborted();
148:      const windows = process.platform === "win32";
149:      const child = spawn(windows ? "powershell.exe" : "/bin/bash",
150:        windows ? ["-NoLogo", "-NoProfile", "-NonInteractive", "-Command", command] : ["--noprofile", "--norc", "-c", command],
151:        { cwd: directory, env: toolEnvironment(), windowsHide: true, detached: false, stdio: ["ignore", "pipe", "pipe"] });
152:      child.stdout.on("data", onData); child.stderr.on("data", onData);
153:      let timer: NodeJS.Timeout | undefined;
154:      const abort = () => child.kill();
155:      signal?.addEventListener("abort", abort, { once: true });
156:      let timedOut = false;
157:      if (timeout && timeout > 0) timer = setTimeout(() => { timedOut = true; abort(); }, timeout * 1000);
158:      try {
159:        const exitCode = await new Promise<number | null>((res, rej) => { child.once("error", rej); child.once("exit", res); });
160:        signal?.throwIfAborted();
161:        if (timedOut) throw new Error("Command timed out");
162:        return { exitCode };
163:      } finally {
164:        if (timer) clearTimeout(timer);
165:        signal?.removeEventListener("abort", abort);
166:        child.stdout.destroy(); child.stderr.destroy();
167:      }
168:    },
169:  } });
170:  // Retain the SDK schema and output truncation, replace only the execution backend.
171:  shell.name = "shell";
172:  shell.description = `Run a short ${process.platform === "win32" ? "PowerShell" : "Bash"} command in the application. Use this for file searches, builds and type checks; run tests with the run_tests tool instead. ${managedApp ? "Use the app tool to start and stop the application for browser checks." : "Do not start persistent servers; briefly starting the app in the background for a browser-tool check is allowed when instructed."}`;
