174:  const installCapabilityParameters = Type.Object({
175:    id: Type.String({ description: "Approved capability id returned by list_capabilities" }),
176:  });
177:  const listCapabilityTool: ToolDefinition<typeof listCapabilityParameters> = {
178:    name: "list_capabilities",
179:    label: "List approved capabilities",
180:    description: "List controller-approved, task-neutral capability packs and whether each is already installed. The catalog never exposes business code or arbitrary packages.",
181:    promptSnippet: "list_capabilities: inspect approved task-neutral component packs",
182:    parameters: listCapabilityParameters,
183:    executionMode: "sequential",
184:    async execute() {
185:      await assertToolPath(cwd, "frontend/src/ui");
186:      const capabilities = await listCapabilities(cwd);
187:      return { content: [{ type: "text" as const, text: JSON.stringify(capabilities, null, 2) }], details: { capabilities } };
188:    },
189:  };
190:  const installCapabilityTool: ToolDefinition<typeof installCapabilityParameters> = {
191:    name: "install_capability",
192:    label: "Install approved capability",
193:    description: "Install one controller-approved, task-neutral capability pack. Existing differing files are never overwritten; arbitrary npm/git sources are not accepted.",
194:    promptSnippet: "install_capability: install an approved component pack without overwriting existing files",
195:    parameters: installCapabilityParameters,
196:    executionMode: "sequential",
197:    async execute(_toolCallId, { id }) {
198:      await assertToolPath(cwd, "frontend/src/ui");
199:      const result = await installCapability(cwd, id);
200:      return { content: [{ type: "text" as const, text: JSON.stringify(result, null, 2) }], details: result };
201:    },
202:  };
203:  return [guardedRead, ...guardedWritable, shell as unknown as ToolDefinition, createTestTool(cwd), createBrowserTool(),
204:    listCapabilityTool, installCapabilityTool, ...(managedApp ? [createAppTool()] : [])];
205:}
