39:export class PlannerRequestError extends Error {
40:  readonly gatewayFailure?: GatewayFailure;
41:  readonly retryable: boolean;
42:  readonly fatal: boolean;
43:  readonly diagnostics: {
44:    category: PlannerRequestErrorCategory;
45:    message: string;
46:    validationError?: string;
47:    contentPreview?: string;
48:    retryable: boolean;
49:    fatal: boolean;
50:    httpStatus?: number;
