53:  constructor(
54:    readonly category: PlannerRequestErrorCategory,
55:    message: string,
56:    options?: ErrorOptions & { content?: string; apiKey?: string; httpStatus?: number; retryAfter?: string | null },
57:  ) {
58:    super(message, options);
59:    this.name = "PlannerRequestError";
60:    const status = options?.httpStatus;
61:    if (category === "transport") this.gatewayFailure = status === undefined
62:      ? { kind: "unavailable", retryable: true } : httpGatewayFailure(status, options?.retryAfter);
63:    this.retryable = category === "transport" && (status === undefined || status === 408 || status === 429 || status >= 500);
64:    this.fatal = category === "response" || (category === "transport" && !this.retryable);
65:    this.diagnostics = {
66:      category,
67:      retryable: this.retryable,
68:      fatal: this.fatal,
69:      ...(status === undefined ? {} : { httpStatus: status }),
70:      message: sanitizePlannerDiagnostic(message, options?.apiKey),
71:      ...(options?.cause instanceof Error ? {
72:        validationError: sanitizePlannerDiagnostic(options.cause.message, options.apiKey),
73:      } : {}),
74:      ...(options?.content !== undefined ? {
75:        contentPreview: sanitizePlannerDiagnostic(options.content, options.apiKey),
76:      } : {}),
77:    };
78:  }
