230:function extractSseContent(body: string, label: string): { content?: string; usage?: PlannerUsage; cutOff?: boolean } {
231:  let content = "";
232:  let usage: PlannerUsage | undefined;
233:  let finished = false;
234:  let done = false;
235:  let cutOff = false;
236:  for (const block of body.split(/\r\n\r\n|\n\n|\r\r/)) {
237:    const data = block.split(/\r\n|\n|\r/).filter(line => line.startsWith("data:"))
238:      .map(line => line.slice(5).replace(/^ /, "")).join("\n");
239:    if (!data) continue;
240:    if (data.trim() === "[DONE]") { done = true; break; }
241:    let event: unknown;
242:    try { event = JSON.parse(data); }
243:    catch (error) {
244:      // A damaged usage trailer after the terminal choice cannot change the plan.
245:      if (finished && !/"(?:choices|tool_calls)"\s*:/.test(data)) continue;
246:      throw new Error(`${label} stream contains an incomplete content event`, { cause: error });
247:    }
248:    if (typeof event !== "object" || event === null) continue;
249:    const envelope = event as { error?: { message?: string }; usage?: unknown; choices?: Array<{
250:      index?: number; delta?: { content?: unknown }; finish_reason?: unknown; usage?: unknown;
251:    }> };
252:    if (envelope.error) throw new Error(envelope.error.message ?? `${label} stream returned an error`);
253:    const choice = envelope.choices?.find(item => item?.index === 0);
254:    usage = parseUsage(envelope.usage ?? choice?.usage) ?? usage;
255:    if (!choice) continue;
256:    if (typeof choice.delta?.content === "string") content += choice.delta.content;
257:    if (typeof choice.finish_reason === "string") {
258:      if (choice.finish_reason === "length") cutOff = true;
259:      finished = true;
260:    }
261:  }
262:  if (!done && !finished) throw new Error(`${label} stream ended before completion`);
263:  return { ...(content ? { content } : {}), ...(usage ? { usage } : {}), ...(cutOff ? { cutOff } : {}) };
264:}
